/**
 * PersonalCodeOS - Window Manager
 * 브라우저 기반 멀티윈도우 관리자
 */

export class WindowManager {
  constructor(desktop) {
    this.desktop = desktop;
    this.windows = new Map();
    this.focusStack = [];
    this.nextZIndex = 100;
    this.nextId = 1;
    this._setupDesktop();
  }

  _setupDesktop() {
    this.desktop.addEventListener('mousedown', (e) => {
      if (e.target === this.desktop) {
        this._deselectAll();
      }
    });
  }

  /**
   * 새 윈도우 생성
   * @param {Object} opts - { title, content, x, y, width, height, icon, resizable, app }
   */
  createWindow(opts = {}) {
    const id = `win-${this.nextId++}`;
    const config = {
      id,
      title: opts.title || 'Untitled',
      x: opts.x ?? 80 + (this.windows.size * 30),
      y: opts.y ?? 60 + (this.windows.size * 30),
      width: opts.width ?? 700,
      height: opts.height ?? 500,
      minWidth: opts.minWidth ?? 300,
      minHeight: opts.minHeight ?? 200,
      icon: opts.icon ?? '📄',
      resizable: opts.resizable !== false,
      maximized: false,
      minimized: false,
      app: opts.app ?? null,
    };

    const el = this._createElement(config, opts.content);
    this.desktop.appendChild(el);
    this.windows.set(id, { config, el });
    this.focus(id);

    return id;
  }

  _createElement(config, contentEl) {
    const win = document.createElement('div');
    win.className = 'os-window';
    win.id = config.id;
    win.style.cssText = `left:${config.x}px;top:${config.y}px;width:${config.width}px;height:${config.height}px;`;

    win.innerHTML = `
      <div class="win-titlebar" data-win="${config.id}">
        <span class="win-icon">${config.icon}</span>
        <span class="win-title">${config.title}</span>
        <div class="win-controls">
          <button class="win-btn btn-minimize" title="최소화">─</button>
          <button class="win-btn btn-maximize" title="최대화">□</button>
          <button class="win-btn btn-close" title="닫기">✕</button>
        </div>
      </div>
      <div class="win-body"></div>
      ${config.resizable ? '<div class="win-resize-handle"></div>' : ''}
    `;

    const body = win.querySelector('.win-body');
    if (contentEl instanceof HTMLElement) {
      body.appendChild(contentEl);
    } else if (typeof contentEl === 'string') {
      body.innerHTML = contentEl;
    }

    this._bindWindowEvents(win, config);
    return win;
  }

  _bindWindowEvents(win, config) {
    const titlebar = win.querySelector('.win-titlebar');
    const btnMin = win.querySelector('.btn-minimize');
    const btnMax = win.querySelector('.btn-maximize');
    const btnClose = win.querySelector('.btn-close');
    const resizeHandle = win.querySelector('.win-resize-handle');

    // 포커스
    win.addEventListener('mousedown', () => this.focus(config.id));

    // 드래그
    this._makeDraggable(win, titlebar, config);

    // 리사이즈
    if (resizeHandle) {
      this._makeResizable(win, resizeHandle, config);
    }

    // 버튼
    btnMin?.addEventListener('click', (e) => { e.stopPropagation(); this.minimize(config.id); });
    btnMax?.addEventListener('click', (e) => { e.stopPropagation(); this.toggleMaximize(config.id); });
    btnClose?.addEventListener('click', (e) => { e.stopPropagation(); this.close(config.id); });

    // 더블클릭 최대화
    titlebar.addEventListener('dblclick', () => this.toggleMaximize(config.id));
  }

  _makeDraggable(win, handle, config) {
    let startX, startY, startLeft, startTop, dragging = false;

    handle.addEventListener('mousedown', (e) => {
      if (e.target.classList.contains('win-btn')) return;
      if (config.maximized) return;
      dragging = true;
      startX = e.clientX;
      startY = e.clientY;
      startLeft = win.offsetLeft;
      startTop = win.offsetTop;
      e.preventDefault();
    });

    document.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      const newLeft = Math.max(0, startLeft + dx);
      const newTop = Math.max(0, startTop + dy);
      win.style.left = `${newLeft}px`;
      win.style.top = `${newTop}px`;
      config.x = newLeft;
      config.y = newTop;
    });

    document.addEventListener('mouseup', () => { dragging = false; });
  }

  _makeResizable(win, handle, config) {
    let startX, startY, startW, startH, resizing = false;

    handle.addEventListener('mousedown', (e) => {
      resizing = true;
      startX = e.clientX;
      startY = e.clientY;
      startW = win.offsetWidth;
      startH = win.offsetHeight;
      e.preventDefault();
      e.stopPropagation();
    });

    document.addEventListener('mousemove', (e) => {
      if (!resizing) return;
      const newW = Math.max(config.minWidth, startW + (e.clientX - startX));
      const newH = Math.max(config.minHeight, startH + (e.clientY - startY));
      win.style.width = `${newW}px`;
      win.style.height = `${newH}px`;
      config.width = newW;
      config.height = newH;
      // 리사이즈 이벤트 발생 (에디터 갱신용)
      win.dispatchEvent(new CustomEvent('win-resize', { detail: { width: newW, height: newH } }));
    });

    document.addEventListener('mouseup', () => { resizing = false; });
  }

  focus(id) {
    const entry = this.windows.get(id);
    if (!entry) return;

    // 이전 포커스 해제
    this.windows.forEach((w) => w.el.classList.remove('focused'));

    entry.el.classList.add('focused');
    entry.el.style.zIndex = ++this.nextZIndex;

    this.focusStack = this.focusStack.filter(i => i !== id);
    this.focusStack.push(id);

    this._updateTaskbar();
  }

  minimize(id) {
    const entry = this.windows.get(id);
    if (!entry) return;
    entry.config.minimized = true;
    entry.el.style.display = 'none';
    this._updateTaskbar();
  }

  restore(id) {
    const entry = this.windows.get(id);
    if (!entry) return;
    entry.config.minimized = false;
    entry.el.style.display = '';
    this.focus(id);
  }

  toggleMaximize(id) {
    const entry = this.windows.get(id);
    if (!entry) return;
    const { config, el } = entry;

    if (config.maximized) {
      el.style.left = `${config.restoreX}px`;
      el.style.top = `${config.restoreY}px`;
      el.style.width = `${config.restoreW}px`;
      el.style.height = `${config.restoreH}px`;
      el.classList.remove('maximized');
      config.maximized = false;
    } else {
      config.restoreX = config.x;
      config.restoreY = config.y;
      config.restoreW = config.width;
      config.restoreH = config.height;
      const taskbarH = 48;
      el.style.left = '0';
      el.style.top = '0';
      el.style.width = `${this.desktop.offsetWidth}px`;
      el.style.height = `${this.desktop.offsetHeight - taskbarH}px`;
      el.classList.add('maximized');
      config.maximized = true;
    }
    el.dispatchEvent(new CustomEvent('win-resize'));
  }

  close(id) {
    const entry = this.windows.get(id);
    if (!entry) return;

    // 앱 정리
    if (entry.config.app?.destroy) {
      entry.config.app.destroy();
    }

    entry.el.remove();
    this.windows.delete(id);
    this.focusStack = this.focusStack.filter(i => i !== id);

    // 다음 윈도우 포커스
    if (this.focusStack.length > 0) {
      this.focus(this.focusStack[this.focusStack.length - 1]);
    }

    this._updateTaskbar();
  }

  setTitle(id, title) {
    const entry = this.windows.get(id);
    if (!entry) return;
    entry.config.title = title;
    const titleEl = entry.el.querySelector('.win-title');
    if (titleEl) titleEl.textContent = title;
    this._updateTaskbar();
  }

  _deselectAll() {
    this.windows.forEach(w => w.el.classList.remove('focused'));
  }

  _updateTaskbar() {
    const taskbar = document.getElementById('taskbar-windows');
    if (!taskbar) return;
    taskbar.innerHTML = '';

    this.windows.forEach((entry, id) => {
      const btn = document.createElement('button');
      btn.className = 'taskbar-win-btn' + (entry.el.classList.contains('focused') ? ' active' : '');
      btn.innerHTML = `${entry.config.icon} <span>${entry.config.title}</span>`;
      btn.title = entry.config.title;
      btn.addEventListener('click', () => {
        if (entry.config.minimized) {
          this.restore(id);
        } else if (entry.el.classList.contains('focused')) {
          this.minimize(id);
        } else {
          this.focus(id);
        }
      });
      taskbar.appendChild(btn);
    });
  }
}

