/**
 * PersonalCodeOS - Storage Layer
 * OPFS (Origin Private File System) + IndexedDB 통합 추상화
 *
 * - OPFS: 실제 파일 내용 (바이너리 안전, 고성능)
 * - IndexedDB: 메타데이터, VCS 데이터, 설정
 */

const DB_NAME = 'personal-code-os';
const DB_VERSION = 1;

export class FileSystem {
  constructor() {
    this.db = null;
    this.opfsRoot = null;
    this._ready = this._init();
  }

  async ready() {
    return this._ready;
  }

  async _init() {
    this.db = await this._openDB();
    if ('storage' in navigator && 'getDirectory' in navigator.storage) {
      this.opfsRoot = await navigator.storage.getDirectory();
    }
  }

  _openDB() {
    return new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME, DB_VERSION);

      req.onupgradeneeded = (e) => {
        const db = e.target.result;

        // 파일 메타데이터
        if (!db.objectStoreNames.contains('files')) {
          const files = db.createObjectStore('files', { keyPath: 'path' });
          files.createIndex('parent', 'parent', { unique: false });
          files.createIndex('mtime', 'mtime', { unique: false });
        }

        // VCS 오브젝트 (blob/tree/commit)
        if (!db.objectStoreNames.contains('objects')) {
          db.createObjectStore('objects', { keyPath: 'hash' });
        }

        // 브랜치/태그 참조
        if (!db.objectStoreNames.contains('refs')) {
          db.createObjectStore('refs', { keyPath: 'name' });
        }

        // 설정
        if (!db.objectStoreNames.contains('config')) {
          db.createObjectStore('config', { keyPath: 'key' });
        }

        // REPL 히스토리
        if (!db.objectStoreNames.contains('repl-history')) {
          const hist = db.createObjectStore('repl-history', { keyPath: 'id', autoIncrement: true });
          hist.createIndex('runtime', 'runtime', { unique: false });
        }
      };

      req.onsuccess = (e) => resolve(e.target.result);
      req.onerror = (e) => reject(e.target.error);
    });
  }

  // ─── IndexedDB 헬퍼 ────────────────────────────────────────────

  async dbGet(store, key) {
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction(store, 'readonly');
      const req = tx.objectStore(store).get(key);
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }

  async dbPut(store, value) {
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction(store, 'readwrite');
      const req = tx.objectStore(store).put(value);
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }

  async dbDelete(store, key) {
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction(store, 'readwrite');
      const req = tx.objectStore(store).delete(key);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  }

  async dbGetAll(store, indexName, query) {
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction(store, 'readonly');
      const os = tx.objectStore(store);
      const req = indexName ? os.index(indexName).getAll(query) : os.getAll();
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }

  // ─── 파일 시스템 API ───────────────────────────────────────────

  /**
   * 파일 쓰기
   * @param {string} path - 절대 경로 (예: /projects/hello.fl)
   * @param {string|ArrayBuffer} content - 내용
   */
  async writeFile(path, content) {
    await this._ready;
    const normalized = this._normalizePath(path);

    // OPFS 백엔드
    if (this.opfsRoot) {
      await this._opfsWrite(normalized, content);
    }

    // 메타데이터
    const meta = {
      path: normalized,
      parent: this._parentPath(normalized),
      name: this._basename(normalized),
      type: 'file',
      size: typeof content === 'string' ? new TextEncoder().encode(content).length : content.byteLength,
      mtime: Date.now(),
      encoding: typeof content === 'string' ? 'utf8' : 'binary',
    };

    // OPFS 없으면 IndexedDB에 내용도 저장
    if (!this.opfsRoot) {
      meta.content = typeof content === 'string' ? content : this._ab2b64(content);
    }

    await this.dbPut('files', meta);
    return meta;
  }

  /**
   * 파일 읽기
   */
  async readFile(path, encoding = 'utf8') {
    await this._ready;
    const normalized = this._normalizePath(path);

    if (this.opfsRoot) {
      return await this._opfsRead(normalized, encoding);
    }

    // 폴백: IndexedDB 내용
    const meta = await this.dbGet('files', normalized);
    if (!meta) throw new Error(`File not found: ${path}`);
    if (meta.content !== undefined) {
      if (encoding === 'binary') {
        return this._b642ab(meta.content);
      }
      return meta.content;
    }
    throw new Error(`File content not available: ${path}`);
  }

  /**
   * 파일/디렉토리 목록
   */
  async readDir(path) {
    await this._ready;
    const normalized = this._normalizePath(path);
    const entries = await this.dbGetAll('files', 'parent', normalized);
    return entries.map(e => ({
      name: e.name,
      path: e.path,
      type: e.type,
      size: e.size,
      mtime: e.mtime,
    }));
  }

  /**
   * 디렉토리 생성
   */
  async mkdir(path) {
    await this._ready;
    const normalized = this._normalizePath(path);

    if (this.opfsRoot) {
      await this._opfsMkdir(normalized);
    }

    const meta = {
      path: normalized,
      parent: this._parentPath(normalized),
      name: this._basename(normalized),
      type: 'dir',
      size: 0,
      mtime: Date.now(),
    };
    await this.dbPut('files', meta);
  }

  /**
   * 파일 삭제
   */
  async unlink(path) {
    await this._ready;
    const normalized = this._normalizePath(path);
    if (this.opfsRoot) {
      await this._opfsUnlink(normalized);
    }
    await this.dbDelete('files', normalized);
  }

  /**
   * 파일 존재 확인
   */
  async exists(path) {
    await this._ready;
    const meta = await this.dbGet('files', this._normalizePath(path));
    return !!meta;
  }

  // ─── OPFS 내부 구현 ────────────────────────────────────────────

  async _opfsWrite(path, content) {
    const parts = path.split('/').filter(Boolean);
    let dir = this.opfsRoot;

    for (let i = 0; i < parts.length - 1; i++) {
      dir = await dir.getDirectoryHandle(parts[i], { create: true });
    }

    const filename = parts[parts.length - 1];
    const fh = await dir.getFileHandle(filename, { create: true });
    const writable = await fh.createWritable();
    const data = typeof content === 'string' ? new TextEncoder().encode(content) : content;
    await writable.write(data);
    await writable.close();
  }

  async _opfsRead(path, encoding) {
    const parts = path.split('/').filter(Boolean);
    let dir = this.opfsRoot;

    for (let i = 0; i < parts.length - 1; i++) {
      dir = await dir.getDirectoryHandle(parts[i]);
    }

    const filename = parts[parts.length - 1];
    const fh = await dir.getFileHandle(filename);
    const file = await fh.getFile();

    if (encoding === 'binary') {
      return file.arrayBuffer();
    }
    return file.text();
  }

  async _opfsMkdir(path) {
    const parts = path.split('/').filter(Boolean);
    let dir = this.opfsRoot;
    for (const part of parts) {
      dir = await dir.getDirectoryHandle(part, { create: true });
    }
  }

  async _opfsUnlink(path) {
    const parts = path.split('/').filter(Boolean);
    let dir = this.opfsRoot;
    for (let i = 0; i < parts.length - 1; i++) {
      dir = await dir.getDirectoryHandle(parts[i]);
    }
    const filename = parts[parts.length - 1];
    await dir.removeEntry(filename).catch(() => {});
  }

  // ─── 유틸 ─────────────────────────────────────────────────────

  _normalizePath(path) {
    return '/' + path.replace(/^\/+|\/+$/g, '').replace(/\/+/g, '/');
  }

  _parentPath(path) {
    const parts = path.split('/').filter(Boolean);
    if (parts.length <= 1) return '/';
    return '/' + parts.slice(0, -1).join('/');
  }

  _basename(path) {
    const parts = path.split('/').filter(Boolean);
    return parts[parts.length - 1] || '/';
  }

  _ab2b64(buf) {
    const bytes = new Uint8Array(buf);
    let str = '';
    for (const b of bytes) str += String.fromCharCode(b);
    return btoa(str);
  }

  _b642ab(b64) {
    const str = atob(b64);
    const buf = new ArrayBuffer(str.length);
    const view = new Uint8Array(buf);
    for (let i = 0; i < str.length; i++) view[i] = str.charCodeAt(i);
    return buf;
  }

  // ─── SHA-256 해시 (VCS 용) ─────────────────────────────────────

  async sha256(data) {
    const encoded = typeof data === 'string' ? new TextEncoder().encode(data) : data;
    const hashBuf = await crypto.subtle.digest('SHA-256', encoded);
    return Array.from(new Uint8Array(hashBuf)).map(b => b.toString(16).padStart(2, '0')).join('');
  }
}

