 * 오브젝트 타입:
 *   blob   - 파일 내용 (hash = SHA-256(content))
 *   tree   - 디렉토리 스냅샷 { name → { type, hash } }
 *   commit - 커밋 { tree, parent, message, author, timestamp }
 */

import { fs } from '../storage/fs.js';

export class Repository {
  constructor(repoPath) {
    this.path = repoPath;
    this.HEAD = 'refs/heads/main';
  }

  // ─── 초기화 ───────────────────────────────────────────────────

  async init() {
    await fs.ready();
    const existing = await fs.dbGet('refs', `${this.path}:HEAD`);
    if (existing) return false; // 이미 초기화됨

    await fs.dbPut('refs', { name: `${this.path}:HEAD`, value: 'refs/heads/main' });
    console.log(`[VCS] Initialized repository: ${this.path}`);
    return true;
  }

  // ─── 오브젝트 저장 ─────────────────────────────────────────────

  async _storeBlob(content) {
    const hash = await fs.sha256(content);
    const existing = await fs.dbGet('objects', hash);
    if (!existing) {
      await fs.dbPut('objects', {
        hash,
        type: 'blob',
        data: typeof content === 'string' ? content : null,
        dataB64: typeof content !== 'string' ? this._ab2b64(content) : null,
      });
    }
    return hash;
  }

  async _storeTree(entries) {
    // entries: { name: { type: 'blob'|'tree', hash } }
    const serialized = JSON.stringify(entries, Object.keys(entries).sort());
    const hash = await fs.sha256(serialized);
    const existing = await fs.dbGet('objects', hash);
    if (!existing) {
      await fs.dbPut('objects', { hash, type: 'tree', entries });
    }
    return hash;
  }

  async _storeCommit(commitData) {
    const serialized = JSON.stringify(commitData);
    const hash = await fs.sha256(serialized);
    await fs.dbPut('objects', { hash, type: 'commit', ...commitData });
    return hash;
  }

  // ─── 커밋 ─────────────────────────────────────────────────────

  /**
   * 작업 트리 전체를 커밋
   * @param {string} message
   * @param {string} author
   */
  async commit(message, author = 'Anonymous') {
    await fs.ready();

    // 작업 트리 스냅샷 (루트부터)
    const treeHash = await this._snapshotDir(this.path);
    const parent = await this._getHead();

    const commitData = {
      tree: treeHash,
      parent: parent || null,
      message,
      author,
      timestamp: Date.now(),
      repo: this.path,
    };

    const commitHash = await this._storeCommit(commitData);
    await this._setRef(this.HEAD, commitHash);

    return { hash: commitHash, ...commitData };
  }

  async _snapshotDir(dirPath) {
    const entries = await fs.readDir(dirPath);
    const treeEntries = {};

    for (const entry of entries) {
      if (entry.type === 'file') {
        const content = await fs.readFile(entry.path);
        const hash = await this._storeBlob(content);
        treeEntries[entry.name] = { type: 'blob', hash };
      } else if (entry.type === 'dir') {
        const hash = await this._snapshotDir(entry.path);
        treeEntries[entry.name] = { type: 'tree', hash };
      }
    }

    return this._storeTree(treeEntries);
  }

  // ─── 브랜치/HEAD ──────────────────────────────────────────────

  async _getHead() {
    const headRef = await fs.dbGet('refs', `${this.path}:HEAD`);
    if (!headRef) return null;
    const ref = await fs.dbGet('refs', `${this.path}:${headRef.value}`);
    return ref ? ref.value : null;
  }

  async _setRef(refName, hash) {
    await fs.dbPut('refs', { name: `${this.path}:${refName}`, value: hash });
  }

  async createBranch(name) {
    const head = await this._getHead();
    if (!head) throw new Error('No commits yet');
    await this._setRef(`refs/heads/${name}`, head);
    return name;
  }

  async checkout(name) {
    const ref = await fs.dbGet('refs', `${this.path}:refs/heads/${name}`);
    if (!ref) throw new Error(`Branch not found: ${name}`);
    this.HEAD = `refs/heads/${name}`;
    await fs.dbPut('refs', { name: `${this.path}:HEAD`, value: this.HEAD });
    return name;
  }

  async listBranches() {
    const all = await fs.dbGetAll('refs');
    const prefix = `${this.path}:refs/heads/`;
    return all
      .filter(r => r.name.startsWith(prefix))
      .map(r => ({
        name: r.name.slice(prefix.length),
        hash: r.value,
        current: r.name === `${this.path}:${this.HEAD}`,
      }));
  }

  // ─── 히스토리 ─────────────────────────────────────────────────

  async log(limit = 20) {
    const head = await this._getHead();
    if (!head) return [];

    const commits = [];
    let hash = head;

    while (hash && commits.length < limit) {
      const obj = await fs.dbGet('objects', hash);
      if (!obj || obj.type !== 'commit') break;
      commits.push({ hash, ...obj });
      hash = obj.parent;
    }

    return commits;
  }

  // ─── Diff ────────────────────────────────────────────────────

  async diff(hashA, hashB) {
    const commitA = await fs.dbGet('objects', hashA);
    const commitB = await fs.dbGet('objects', hashB);
    if (!commitA || !commitB) throw new Error('Commit not found');

    const treeDiff = await this._diffTrees(commitA.tree, commitB.tree, '/');
    return treeDiff;
  }

  async _diffTrees(hashA, hashB, path) {
    const treeA = hashA ? (await fs.dbGet('objects', hashA))?.entries ?? {} : {};
    const treeB = hashB ? (await fs.dbGet('objects', hashB))?.entries ?? {} : {};

    const result = [];
    const allKeys = new Set([...Object.keys(treeA), ...Object.keys(treeB)]);

    for (const key of allKeys) {
      const a = treeA[key];
      const b = treeB[key];
      const fullPath = `${path}${key}`;

      if (!a && b) {
        result.push({ type: 'added', path: fullPath, hash: b.hash });
      } else if (a && !b) {
        result.push({ type: 'deleted', path: fullPath, hash: a.hash });
      } else if (a.hash !== b.hash) {
        if (a.type === 'blob') {
          result.push({ type: 'modified', path: fullPath, oldHash: a.hash, newHash: b.hash });
        } else {
          const subDiff = await this._diffTrees(a.hash, b.hash, `${fullPath}/`);
          result.push(...subDiff);
        }
      }
    }

    return result;
  }

  // ─── 오브젝트 조회 ─────────────────────────────────────────────

  async getBlob(hash) {
    const obj = await fs.dbGet('objects', hash);
    if (!obj || obj.type !== 'blob') return null;
    return obj.data ?? this._b642str(obj.dataB64);
  }

  async getStatus() {
    const head = await this._getHead();
    if (!head) return { staged: [], unstaged: [], untracked: [] };

    const lastCommit = await fs.dbGet('objects', head);
    const lastTree = lastCommit?.tree;

    const currentFiles = await this._getAllFiles(this.path);
    const committedFiles = lastTree ? await this._treeToMap(lastTree, '/') : {};

    const status = { modified: [], added: [], deleted: [] };

    for (const [path, content] of Object.entries(currentFiles)) {
      const hash = await fs.sha256(content);
      if (!committedFiles[path]) {
        status.added.push(path);
      } else if (committedFiles[path] !== hash) {
        status.modified.push(path);
      }
    }

    for (const path of Object.keys(committedFiles)) {
      if (!currentFiles[path]) {
        status.deleted.push(path);
      }
    }

    return status;
  }

  async _getAllFiles(dirPath, map = {}) {
    const entries = await fs.readDir(dirPath).catch(() => []);
    for (const entry of entries) {
      if (entry.type === 'file') {
        map[entry.path] = await fs.readFile(entry.path).catch(() => '');
      } else {
        await this._getAllFiles(entry.path, map);
      }
    }
    return map;
  }

  async _treeToMap(treeHash, prefix, map = {}) {
    const tree = await fs.dbGet('objects', treeHash);
    if (!tree) return map;
    for (const [name, entry] of Object.entries(tree.entries ?? {})) {
      if (entry.type === 'blob') {
        map[`${prefix}${name}`] = entry.hash;
      } else {
        await this._treeToMap(entry.hash, `${prefix}${name}/`, map);
      }
    }
    return map;
  }

  _ab2b64(buf) {
    const bytes = new Uint8Array(buf);
    let str = '';
    for (const b of bytes) str += String.fromCharCode(b);
    return btoa(str);
  }

  _b642str(b64) {
    return atob(b64);
  }
}

