/**
 * PersonalCodeOS - Runtime Manager
 * WASM 기반 다중 언어 런타임 관리
 *
 * 지원 런타임:
 *   - fv-lang:  FV-Lang 함수형 언어 (자체 WASM)
 *   - python:   Pyodide (CPython → WASM)
 *   - javascript: 브라우저 내장 eval (샌드박스)
 *   - mini-c:   Mini C 컴파일러 (자체 WASM, Phase 2)
 */

export class RuntimeManager {
  constructor() {
    this.runtimes = new Map();
    this.loading = new Map();
    this._setupBuiltins();
  }

  _setupBuiltins() {
    // JavaScript는 항상 사용 가능
    this.runtimes.set('javascript', new JavaScriptRuntime());
    this.runtimes.set('js', this.runtimes.get('javascript'));
  }

  /**
   * 파일 확장자 → 런타임 이름
   */
  detectRuntime(filename) {
    const ext = filename.split('.').pop()?.toLowerCase();
    const map = {
      'fl': 'fv-lang',
      'fv': 'fv-lang',
      'py': 'python',
      'js': 'javascript',
      'mjs': 'javascript',
      'c': 'mini-c',
      'h': 'mini-c',
    };
    return map[ext] ?? 'javascript';
  }

  /**
   * 런타임 로드 (lazy loading)
   */
  async loadRuntime(name) {
    if (this.runtimes.has(name)) return this.runtimes.get(name);
    if (this.loading.has(name)) return this.loading.get(name);

    let promise;

    switch (name) {
      case 'fv-lang':
        promise = FVLangRuntime.load().then(rt => {
          this.runtimes.set('fv-lang', rt);
          this.runtimes.set('fl', rt);
          this.runtimes.set('fv', rt);
          this.loading.delete(name);
          return rt;
        });
        break;

      case 'python':
        promise = PyodideRuntime.load().then(rt => {
          this.runtimes.set('python', rt);
          this.runtimes.set('py', rt);
          this.loading.delete(name);
          return rt;
        });
        break;

      default:
        throw new Error(`Unknown runtime: ${name}`);
    }

    this.loading.set(name, promise);
    return promise;
  }

  /**
   * 코드 실행
   * @param {string} code - 소스코드
   * @param {string} runtime - 런타임 이름
   * @param {Object} opts - { stdin, args, timeout }
   * @returns {Promise<ExecutionResult>}
   */
  async execute(code, runtime, opts = {}) {
    let rt = this.runtimes.get(runtime);
    if (!rt) {
      try {
        rt = await this.loadRuntime(runtime);
      } catch (e) {
        return {
          stdout: '',
          stderr: `Runtime '${runtime}' not available: ${e.message}\n(Try refreshing the page after loading the runtime)`,
          exitCode: 1,
          duration: 0,
        };
      }
    }

    const start = performance.now();
    try {
      const result = await Promise.race([
        rt.run(code, opts),
        new Promise((_, reject) =>
          setTimeout(() => reject(new Error('Execution timeout (10s)')), opts.timeout ?? 10000)
        ),
      ]);
      result.duration = performance.now() - start;
      return result;
    } catch (e) {
      return {
        stdout: '',
        stderr: e.message,
        exitCode: 1,
        duration: performance.now() - start,
      };
    }
  }

  /**
   * 로드된 런타임 목록
   */
  getLoadedRuntimes() {
    const seen = new Set();
    const result = [];
    for (const [name, rt] of this.runtimes) {
      if (!seen.has(rt)) {
        seen.add(rt);
        result.push({ name, status: rt.status ?? 'ready', version: rt.version ?? '?' });
      }
    }
    return result;
  }
}

// ─── JavaScript 런타임 ─────────────────────────────────────────────

class JavaScriptRuntime {
  constructor() {
    this.status = 'ready';
    this.version = 'Browser JS';
  }

  async run(code, opts = {}) {
    const logs = [];
    const errors = [];

    // 샌드박스: console 가로채기
    const sandbox = {
      console: {
        log: (...args) => logs.push(args.map(a => this._fmt(a)).join(' ')),
        error: (...args) => errors.push(args.map(a => this._fmt(a)).join(' ')),
        warn: (...args) => logs.push('[warn] ' + args.map(a => this._fmt(a)).join(' ')),
        info: (...args) => logs.push(args.map(a => this._fmt(a)).join(' ')),
      },
    };

    let exitCode = 0;
    let returnVal;

    try {
      // Function으로 새 스코프 생성
      const fn = new Function('console', `"use strict";\n${code}`);
      returnVal = await fn(sandbox.console);
      if (returnVal !== undefined) {
        logs.push(this._fmt(returnVal));
      }
    } catch (e) {
      errors.push(e.message);
      exitCode = 1;
    }

    return {
      stdout: logs.join('\n'),
      stderr: errors.join('\n'),
      exitCode,
    };
  }

  _fmt(v) {
    if (v === null) return 'null';
    if (v === undefined) return 'undefined';
    if (typeof v === 'object') {
      try { return JSON.stringify(v, null, 2); } catch { return String(v); }
    }
    return String(v);
  }
}

// ─── FV-Lang 런타임 ────────────────────────────────────────────────

class FVLangRuntime {
  constructor(instance) {
    this.instance = instance;
    this.status = 'ready';
    this.version = 'FV-Lang 0.1.0 (WASM)';
  }

  static async load() {
    // WASM 파일 시도
    try {
      const wasmUrl = '/wasm/fv-lang.wasm';
      const response = await fetch(wasmUrl);
      if (!response.ok) throw new Error('WASM not found');
      const bytes = await response.arrayBuffer();
      const { instance } = await WebAssembly.instantiate(bytes, {
        env: {
          print: (ptr, len) => console.log('WASM print:', ptr, len),
        }
      });
      return new FVLangRuntime(instance);
    } catch {
      // 폴백: JS 인터프리터
      console.log('[FV-Lang] WASM not available, using JS interpreter');
      return new FVLangJSRuntime();
    }
  }

  async run(code, opts = {}) {
    // WASM 인터페이스 (Phase 2에서 구현)
    return { stdout: '', stderr: 'WASM runtime not yet implemented', exitCode: 1 };
  }
}

// FV-Lang 순수 JS 인터프리터 (Phase 1 폴백)
class FVLangJSRuntime {
  constructor() {
    this.status = 'ready';
    this.version = 'FV-Lang 0.1.0 (JS interpreter)';
  }

  async run(code, opts = {}) {
    const logs = [];
    const errors = [];

    try {
      const tokens = this._tokenize(code);
      const ast = this._parse(tokens);
      const result = this._eval(ast, {}, logs);
      if (result !== undefined && result !== null) {
        logs.push(this._fmt(result));
      }
    } catch (e) {
      errors.push(`[FV-Lang Error] ${e.message}`);
      return { stdout: logs.join('\n'), stderr: errors.join('\n'), exitCode: 1 };
    }

    return {
      stdout: logs.join('\n'),
      stderr: errors.join('\n'),
      exitCode: 0,
    };
  }

  _tokenize(code) {
    const tokens = [];
    let i = 0;
    while (i < code.length) {
      // 공백 스킵
      if (/\s/.test(code[i])) { i++; continue; }

      // 주석
      if (code[i] === '#') {
        while (i < code.length && code[i] !== '\n') i++;
        continue;
      }

      // 문자열
      if (code[i] === '"') {
        let j = i + 1;
        while (j < code.length && code[j] !== '"') {
          if (code[j] === '\\') j++;
          j++;
        }
        tokens.push({ type: 'string', value: code.slice(i + 1, j) });
        i = j + 1;
        continue;
      }

      // 숫자
      if (/[0-9]/.test(code[i])) {
        let j = i;
        while (j < code.length && /[0-9.]/.test(code[j])) j++;
        tokens.push({ type: 'number', value: parseFloat(code.slice(i, j)) });
        i = j;
        continue;
      }

      // 연산자 & 구두점
      const two = code.slice(i, i + 2);
      if (['==', '!=', '<=', '>=', '->', '=>', '::'].includes(two)) {
        tokens.push({ type: 'op', value: two });
        i += 2;
        continue;
      }
      if ('+-*/%<>!(){}[]|&,;:.='.includes(code[i])) {
        tokens.push({ type: 'op', value: code[i] });
        i++;
        continue;
      }

      // 키워드 / 식별자
      if (/[a-zA-Z_]/.test(code[i])) {
        let j = i;
        while (j < code.length && /[a-zA-Z0-9_]/.test(code[j])) j++;
        const word = code.slice(i, j);
        const keywords = new Set(['let', 'fn', 'if', 'else', 'match', 'true', 'false', 'print', 'return', 'type', 'import', 'do', 'end', 'for', 'in', 'while', 'null']);
        tokens.push({ type: keywords.has(word) ? 'keyword' : 'ident', value: word });
        i = j;
        continue;
      }

      i++; // unknown char skip
    }
    return tokens;
  }

  _parse(tokens) {
    let pos = 0;
    const peek = () => tokens[pos];
    const consume = () => tokens[pos++];
    const expect = (v) => {
      const t = consume();
      if (t?.value !== v) throw new Error(`Expected '${v}', got '${t?.value}'`);
      return t;
    };

    function parseExpr() {
      return parseComparison();
    }

    function parseComparison() {
      let left = parseAddSub();
      while (peek() && ['==', '!=', '<', '>', '<=', '>='].includes(peek().value)) {
        const op = consume().value;
        const right = parseAddSub();
        left = { type: 'binary', op, left, right };
      }
      return left;
    }

    function parseAddSub() {
      let left = parseMulDiv();
      while (peek() && ['+', '-'].includes(peek().value)) {
        const op = consume().value;
        const right = parseMulDiv();
        left = { type: 'binary', op, left, right };
      }
      return left;
    }

    function parseMulDiv() {
      let left = parseUnary();
      while (peek() && ['*', '/', '%'].includes(peek().value)) {
        const op = consume().value;
        const right = parseUnary();
        left = { type: 'binary', op, left, right };
      }
      return left;
    }

    function parseUnary() {
      if (peek()?.value === '-') {
        consume();
        return { type: 'unary', op: '-', expr: parseUnary() };
      }
      if (peek()?.value === '!') {
        consume();
        return { type: 'unary', op: '!', expr: parseUnary() };
      }
      return parseCall();
    }

    function parseCall() {
      let expr = parsePrimary();
      while (peek()?.value === '(') {
        consume(); // (
        const args = [];
        while (peek() && peek().value !== ')') {
          args.push(parseExpr());
          if (peek()?.value === ',') consume();
        }
        expect(')');
        expr = { type: 'call', callee: expr, args };
      }
      return expr;
    }

    function parsePrimary() {
      const t = peek();
      if (!t) throw new Error('Unexpected end of input');

      if (t.type === 'number') { consume(); return { type: 'number', value: t.value }; }
      if (t.type === 'string') { consume(); return { type: 'string', value: t.value }; }
      if (t.value === 'true') { consume(); return { type: 'bool', value: true }; }
      if (t.value === 'false') { consume(); return { type: 'bool', value: false }; }
      if (t.value === 'null') { consume(); return { type: 'null' }; }

      if (t.value === '(') {
        consume();
        const expr = parseExpr();
        expect(')');
        return expr;
      }

      if (t.value === '[') {
        consume();
        const items = [];
        while (peek()?.value !== ']') {
          items.push(parseExpr());
          if (peek()?.value === ',') consume();
        }
        expect(']');
        return { type: 'array', items };
      }

      if (t.type === 'ident') {
        consume();
        return { type: 'ident', name: t.value };
      }

      throw new Error(`Unexpected token: '${t.value}'`);
    }

    function parseStatement() {
      const t = peek();
      if (!t) return null;

      // let binding
      if (t.value === 'let') {
        consume();
        const name = consume().value;
        expect('=');
        const value = parseExpr();
        return { type: 'let', name, value };
      }

      // fn definition
      if (t.value === 'fn') {
        consume();
        const name = consume().value;
        expect('(');
        const params = [];
        while (peek()?.value !== ')') {
          params.push(consume().value);
          if (peek()?.value === ',') consume();
        }
        expect(')');
        expect('=');
        const body = parseExpr();
        return { type: 'fn', name, params, body };
      }

      // print
      if (t.value === 'print') {
        consume();
        expect('(');
        const args = [];
        while (peek()?.value !== ')') {
          args.push(parseExpr());
          if (peek()?.value === ',') consume();
        }
        expect(')');
        return { type: 'print', args };
      }

      // if/else
      if (t.value === 'if') {
        consume();
        const cond = parseExpr();
        expect('{');
        const then = [];
        while (peek()?.value !== '}') then.push(parseStatement());
        expect('}');
        let els = null;
        if (peek()?.value === 'else') {
          consume();
          expect('{');
          els = [];
          while (peek()?.value !== '}') els.push(parseStatement());
          expect('}');
        }
        return { type: 'if', cond, then, else: els };
      }

      // return
      if (t.value === 'return') {
        consume();
        const value = parseExpr();
        return { type: 'return', value };
      }

      // expression statement
      const expr = parseExpr();
      return { type: 'expr', expr };
    }

    const stmts = [];
    while (pos < tokens.length) {
      const s = parseStatement();
      if (s) stmts.push(s);
    }
    return { type: 'program', body: stmts };
  }

  _eval(node, env, logs) {
    switch (node.type) {
      case 'program':
        let last;
        for (const stmt of node.body) last = this._eval(stmt, env, logs);
        return last;

      case 'number': return node.value;
      case 'string': return node.value;
      case 'bool': return node.value;
      case 'null': return null;

      case 'ident':
        if (!(node.name in env)) throw new Error(`Undefined variable: ${node.name}`);
        return env[node.name];

      case 'array':
        return node.items.map(item => this._eval(item, env, logs));

      case 'let': {
        const val = this._eval(node.value, env, logs);
        env[node.name] = val;
        return val;
      }

      case 'fn': {
        const fn = (...args) => {
          const fnEnv = { ...env };
          node.params.forEach((p, i) => fnEnv[p] = args[i]);
          return this._eval(node.body, fnEnv, logs);
        };
        fn._name = node.name;
        fn._params = node.params;
        env[node.name] = fn;
        return fn;
      }

      case 'call': {
        const callee = this._eval(node.callee, env, logs);
        if (typeof callee !== 'function') throw new Error(`Not a function: ${node.callee.name}`);
        const args = node.args.map(a => this._eval(a, env, logs));
        return callee(...args);
      }

      case 'print': {
        const vals = node.args.map(a => this._fmt(this._eval(a, env, logs)));
        logs.push(vals.join(' '));
        return null;
      }

      case 'binary': {
        const l = this._eval(node.left, env, logs);
        const r = this._eval(node.right, env, logs);
        switch (node.op) {
          case '+': return typeof l === 'string' ? l + r : l + r;
          case '-': return l - r;
          case '*': return l * r;
          case '/': if (r === 0) throw new Error('Division by zero'); return l / r;
          case '%': return l % r;
          case '==': return l === r;
          case '!=': return l !== r;
          case '<': return l < r;
          case '>': return l > r;
          case '<=': return l <= r;
          case '>=': return l >= r;
        }
        break;
      }

      case 'unary':
        if (node.op === '-') return -this._eval(node.expr, env, logs);
        if (node.op === '!') return !this._eval(node.expr, env, logs);
        break;

      case 'if': {
        const cond = this._eval(node.cond, env, logs);
        const branch = cond ? node.then : node.else;
        if (!branch) return null;
        let res;
        for (const s of branch) res = this._eval(s, env, logs);
        return res ?? null;
      }

      case 'return':
        throw { __return: this._eval(node.value, env, logs) };

      case 'expr':
        return this._eval(node.expr, env, logs);
    }
    return null;
  }

  _fmt(v) {
    if (v === null || v === undefined) return 'null';
    if (Array.isArray(v)) return '[' + v.map(i => this._fmt(i)).join(', ') + ']';
    if (typeof v === 'function') return `<fn ${v._name ?? '?'}(${(v._params ?? []).join(', ')})>`;
    return String(v);
  }
}

// ─── Pyodide 런타임 ────────────────────────────────────────────────

class PyodideRuntime {
  constructor(pyodide) {
    this.pyodide = pyodide;
    this.status = 'ready';
    this.version = `Python ${pyodide.version} (Pyodide)`;
  }

  static async load() {
    if (typeof loadPyodide === 'undefined') {
      // CDN에서 로드
      await new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/pyodide/v0.25.0/full/pyodide.js';
        script.onload = resolve;
        script.onerror = reject;
        document.head.appendChild(script);
      });
    }

    const pyodide = await loadPyodide({
      indexURL: 'https://cdn.jsdelivr.net/pyodide/v0.25.0/full/',
    });
    return new PyodideRuntime(pyodide);
  }

  async run(code, opts = {}) {
    const logs = [];
    const errors = [];

    // stdout/stderr 캡처
    this.pyodide.setStdout({ batched: (s) => logs.push(s) });
    this.pyodide.setStderr({ batched: (s) => errors.push(s) });

    try {
      await this.pyodide.runPythonAsync(code);
    } catch (e) {
      errors.push(e.message);
      return { stdout: logs.join('\n'), stderr: errors.join('\n'), exitCode: 1 };
    }

    return {
      stdout: logs.join('\n'),
      stderr: errors.join('\n'),
      exitCode: 0,
    };
  }
}

