/**
 * PersonalCodeOS - AI Assistant
 * WebLLM / transformers.js 기반 로컬 AI 코드 어시스턴트
 *
 * 완전 오프라인 동작: 클라우드 API 없음
 * 모델: Phi-3-mini (2.7B) or Gemma-2b-it (브라우저 내 추론)
 */

export class AIAssistant {
  constructor() {
    this.engine = null;
    this.status = 'unloaded'; // unloaded | loading | ready | error
    this.model = null;
    this.listeners = new Set();
    this.history = []; // { role, content }[]
    this._systemPrompt = `You are an expert programming assistant embedded in Personal Code OS.
You help with FV-Lang, Python, JavaScript, and C programming.
Always provide concise, correct code examples.
FV-Lang syntax: fn add(a, b) = a + b | let x = 42 | print(x) | if cond { } else { }`;
  }

  on(event, fn) { this.listeners.add({ event, fn }); }
  off(event, fn) { this.listeners = new Set([...this.listeners].filter(l => !(l.event === event && l.fn === fn))); }

  _emit(event, data) {
    for (const l of this.listeners) {
      if (l.event === event) l.fn(data);
    }
  }

  /**
   * 모델 로드 (WebLLM 우선, transformers.js 폴백)
   * @param {string} modelId
   */
  async loadModel(modelId = 'Phi-3-mini-4k-instruct-q4f16_1-MLC') {
    if (this.status === 'loading') return;
    this.status = 'loading';
    this.model = modelId;
    this._emit('status', { status: 'loading', model: modelId });

    try {
      await this._loadWebLLM(modelId);
    } catch (e1) {
      console.warn('[AI] WebLLM failed, trying transformers.js:', e1.message);
      try {
        await this._loadTransformers(modelId);
      } catch (e2) {
        this.status = 'error';
        this._emit('status', { status: 'error', error: e2.message });
        throw new Error(`Failed to load AI model: ${e2.message}`);
      }
    }

    this.status = 'ready';
    this._emit('status', { status: 'ready', model: modelId });
  }

  async _loadWebLLM(modelId) {
    // WebLLM CDN 로드
    if (typeof webllm === 'undefined') {
      await new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.type = 'module';
        script.src = 'https://cdn.jsdelivr.net/npm/@mlc-ai/web-llm@0.2.73/lib/index.min.js';
        script.onload = resolve;
        script.onerror = () => reject(new Error('WebLLM CDN not available'));
        document.head.appendChild(script);
      });
      await new Promise(r => setTimeout(r, 500)); // 모듈 초기화 대기
    }

    const { CreateMLCEngine } = await import('https://cdn.jsdelivr.net/npm/@mlc-ai/web-llm@0.2.73/lib/index.min.js');
    this.engine = await CreateMLCEngine(modelId, {
      initProgressCallback: (report) => {
        this._emit('progress', { progress: report.progress, text: report.text });
      }
    });
    this.engineType = 'webllm';
  }

  async _loadTransformers(modelId) {
    // transformers.js (Xenova)
    const { pipeline } = await import('https://cdn.jsdelivr.net/npm/@xenova/transformers@2.17.2/dist/transformers.min.js');

    const tModelId = 'Xenova/phi-1_5';  // 경량 모델
    this.engine = await pipeline('text-generation', tModelId, {
      progress_callback: (report) => {
        this._emit('progress', { progress: report.progress ?? 0, text: report.status ?? '' });
      }
    });
    this.engineType = 'transformers';
  }

  /**
   * 메시지 전송 (스트리밍 지원)
   * @param {string} message
   * @param {Object} opts - { stream, context }
   */
  async chat(message, opts = {}) {
    if (this.status !== 'ready') {
      return { role: 'assistant', content: '⚠️ AI 모델이 로드되지 않았습니다. 먼저 모델을 로드해주세요.' };
    }

    this.history.push({ role: 'user', content: message });

    const messages = [
      { role: 'system', content: this._systemPrompt },
      ...this.history.slice(-10), // 최근 10턴만 컨텍스트
    ];

