    try {
      if (this.engineType === 'webllm') {
        if (opts.stream) {
          const stream = await this.engine.chat.completions.create({
            messages,
            stream: true,
            temperature: 0.7,
            max_tokens: 512,
          });
          for await (const chunk of stream) {
            const delta = chunk.choices[0]?.delta?.content ?? '';
            response += delta;
            this._emit('token', { token: delta, accumulated: response });
          }
        } else {
          const result = await this.engine.chat.completions.create({
            messages,
            temperature: 0.7,
            max_tokens: 512,
          });
          response = result.choices[0].message.content;
        }
      } else if (this.engineType === 'transformers') {
        const prompt = messages.map(m => `${m.role}: ${m.content}`).join('\n') + '\nassistant:';
        const result = await this.engine(prompt, { max_new_tokens: 256 });
        response = result[0]?.generated_text?.split('assistant:').pop()?.trim() ?? '';
      }
    } catch (e) {
      response = `AI 오류: ${e.message}`;
    }

    const assistantMsg = { role: 'assistant', content: response };
    this.history.push(assistantMsg);
    this._emit('message', assistantMsg);
    return assistantMsg;
  }

  /**
   * 코드 자동완성
   * @param {string} code - 현재 코드 (커서 위치까지)
   * @param {string} runtime - 언어/런타임
   */
  async complete(code, runtime = 'fv-lang') {
    if (this.status !== 'ready') return null;

    const prompt = `Complete this ${runtime} code. Return only the completion, not the full code:
\`\`\`${runtime}
${code}
\`\`\`
Completion:`;

    const messages = [
      { role: 'system', content: 'You are a code completion engine. Return only the code completion, nothing else.' },
      { role: 'user', content: prompt },
    ];

    try {
      if (this.engineType === 'webllm') {
        const result = await this.engine.chat.completions.create({
          messages,
          temperature: 0.2,
          max_tokens: 128,
          stop: ['\n\n', '```'],
        });
        return result.choices[0].message.content.trim();
      }
    } catch {
      return null;
    }
    return null;
  }

  /**
   * 코드 설명
   */
  async explain(code, runtime = 'javascript') {
    return this.chat(`다음 ${runtime} 코드를 한국어로 간단히 설명해주세요:\n\`\`\`${runtime}\n${code}\n\`\`\``);
  }

  /**
   * 버그 수정 제안
   */
  async fix(code, error, runtime = 'javascript') {
    return this.chat(`다음 ${runtime} 코드에서 오류가 발생했습니다:\n\n코드:\n\`\`\`${runtime}\n${code}\n\`\`\`\n\n오류:\n${error}\n\n수정 방법을 알려주세요.`);
  }

  clearHistory() {
    this.history = [];
  }

  getStatus() {
    return {
      status: this.status,
      model: this.model,
      engineType: this.engineType ?? null,
      historyLength: this.history.length,
    };
  }

  // 오프라인 폴백: 규칙 기반 응답
  static getRuleBasedResponse(message) {
    const msg = message.toLowerCase();

    if (msg.includes('fv-lang') || msg.includes('fv lang')) {
      return `FV-Lang 기본 문법:
\`\`\`fv
# 변수 선언
let x = 42
let name = "FV-Lang"

# 함수 정의
fn add(a, b) = a + b
fn greet(name) = "Hello, " + name

# 출력
print(add(1, 2))      # 3
print(greet(name))     # Hello, FV-Lang

# 조건문
if x > 10 {
  print("big")
} else {
  print("small")
}
\`\`\``;
    }

    if (msg.includes('hello') || msg.includes('안녕')) {
      return '안녕하세요! Personal Code OS AI 어시스턴트입니다. FV-Lang, Python, JavaScript 코드 작성을 도와드릴게요.';
    }

    return null; // AI 처리 필요
  }
}

export const ai = new AIAssistant();

