/**
 * PersonalCodeOS - Code Editor
 * CodeMirror 6 기반 코드 편집기
 * 언어별 하이라이팅, 자동완성, AI 인라인 제안
 */

export class CodeEditor {
  constructor(container, opts = {}) {
    this.container = container;
    this.opts = {
      runtime: opts.runtime ?? 'javascript',
      theme: opts.theme ?? 'dark',
      fontSize: opts.fontSize ?? 14,
      tabSize: opts.tabSize ?? 2,
      onSave: opts.onSave ?? null,
      onChange: opts.onChange ?? null,
      ai: opts.ai ?? null,
    };

    this.view = null;
    this.extensions = null;
    this._cmLoaded = false;
    this._init();
  }

  async _init() {
    await this._loadCM();
    this._createView();
  }

  async _loadCM() {
    if (this._cmLoaded) return;

    // CodeMirror 6 ESM 모듈 (CDN)
    const base = 'https://cdn.jsdelivr.net/npm/@codemirror';

    const [
      { EditorView, keymap, lineNumbers, drawSelection, highlightActiveLine },
      { defaultKeymap, history, historyKeymap, indentWithTab },
      { EditorState },
      { javascript },
      { python },
      { oneDark },
    ] = await Promise.all([
      import(`${base}/view@6.35.3/dist/index.js`),
      import(`${base}/commands@6.7.1/dist/index.js`),
      import(`${base}/state@6.5.2/dist/index.js`),
      import(`${base}/lang-javascript@6.2.2/dist/index.js`).catch(() => ({ javascript: () => [] })),
      import(`${base}/lang-python@6.1.7/dist/index.js`).catch(() => ({ python: () => [] })),
      import(`${base}/theme-one-dark@6.1.2/dist/index.js`).catch(() => ({ oneDark: [] })),
    ]);

    this._cm = { EditorView, EditorState, keymap, lineNumbers, drawSelection, highlightActiveLine, defaultKeymap, history, historyKeymap, indentWithTab, javascript, python, oneDark };
    this._cmLoaded = true;
  }

  _getLangExtension() {
    const { javascript, python } = this._cm;
    switch (this.opts.runtime) {
      case 'javascript':
      case 'js': return javascript();
      case 'python':
      case 'py': return python();
      case 'fv-lang':
      case 'fl':
      case 'fv': return this._fvLangHighlight();
      default: return [];
    }
  }

  // FV-Lang 기본 하이라이팅 (StreamLanguage 없이 CSS 클래스 활용)
  _fvLangHighlight() {
    const { EditorView } = this._cm;
    return EditorView.theme({
      '.cm-content': { fontFamily: 'JetBrains Mono, monospace' },
    });
  }

  _createView() {
    const { EditorView, EditorState, keymap, lineNumbers, drawSelection, highlightActiveLine,
      defaultKeymap, history, historyKeymap, indentWithTab, oneDark } = this._cm;

    const extensions = [
      lineNumbers(),
      drawSelection(),
      highlightActiveLine(),
      history(),
      this._getLangExtension(),
      oneDark,
      keymap.of([
        ...defaultKeymap,
        ...historyKeymap,
        indentWithTab,
        // Ctrl+S: 저장
        {
          key: 'Mod-s',
          run: () => {
            if (this.opts.onSave) this.opts.onSave(this.getValue());
            return true;
          }
        },
        // Ctrl+Enter: 실행
        {
          key: 'Mod-Enter',
          run: () => {
            this.container.dispatchEvent(new CustomEvent('editor-run', {
              detail: { code: this.getValue(), runtime: this.opts.runtime },
              bubbles: true,
            }));
            return true;
          }
        },
        // Ctrl+Space: AI 완성
        {
          key: 'Mod-Space',
          run: () => {
            this._triggerAIComplete();
            return true;
          }
        },
      ]),
      EditorState.tabSize.of(this.opts.tabSize),
      EditorView.lineWrapping,
      EditorView.updateListener.of((update) => {
        if (update.docChanged && this.opts.onChange) {
          this.opts.onChange(this.getValue());
        }
      }),
      EditorView.theme({
        '&': { height: '100%', fontSize: `${this.opts.fontSize}px` },
        '.cm-scroller': { overflow: 'auto' },
      }),
    ];

    this.view = new EditorView({
      state: EditorState.create({
        doc: this.opts.initialContent ?? '',
        extensions,
      }),
      parent: this.container,
    });
  }

  getValue() {
    return this.view?.state.doc.toString() ?? '';
  }

  setValue(content) {
    if (!this.view) return;
    this.view.dispatch({
      changes: { from: 0, to: this.view.state.doc.length, insert: content }
    });
  }

  setRuntime(runtime) {
    this.opts.runtime = runtime;
    // 언어 확장 갱신 (리빌드 필요 시)
  }

  focus() {
    this.view?.focus();
  }

  async _triggerAIComplete() {
    if (!this.opts.ai || this.opts.ai.status !== 'ready') return;

    const code = this.getValue();
    const cursor = this.view.state.selection.main.head;
    const before = code.slice(0, cursor);

    const completion = await this.opts.ai.complete(before, this.opts.runtime);
    if (!completion) return;

    // 커서 위치에 삽입
    this.view.dispatch({
      changes: { from: cursor, insert: completion },
    });
  }

  destroy() {
    this.view?.destroy();
  }
}

