/**
 * PersonalCodeOS - Main Application
 * 모든 서브시스템을 연결하는 최상위 오케스트레이터
 */

import { WindowManager } from './shell/window-manager.js';
import { fs } from './storage/fs.js';
import { Repository } from './vcs/repo.js';
import { runtimeManager } from './runtimes/manager.js';
import { ai } from './ai/assistant.js';
import { CodeEditor } from './editor/editor.js';

class PersonalCodeOS {
  constructor() {
    this.wm = null;
    this.openFiles = new Map(); // path → windowId
    this.activeRepo = null;
    this.clock = null;
  }

  async boot() {
    console.log('[OS] Booting Personal Code OS...');

    const desktop = document.getElementById('desktop');
    this.wm = new WindowManager(desktop);

    await fs.ready();
    console.log('[OS] Storage ready');

    // 기본 디렉토리 구조 생성
    await this._initDefaultFS();

    // 시계
    this._startClock();

    // 런처 아이콘 이벤트
    this._bindLauncher();

    // 시작 화면
    await this._showWelcome();

    console.log('[OS] Boot complete');
  }

  async _initDefaultFS() {
    const dirs = ['/home', '/home/projects', '/home/snippets', '/home/notes'];
    for (const dir of dirs) {
      if (!(await fs.exists(dir))) {
        await fs.mkdir(dir);
      }
    }

    // 기본 예제 파일
    if (!(await fs.exists('/home/hello.fl'))) {
      await fs.writeFile('/home/hello.fl', `# FV-Lang Hello World
fn greet(name) = "Hello, " + name

let msg = greet("Personal Code OS")
print(msg)

# 피보나치
fn fib(n) = if n <= 1 { n } else { fib(n - 1) + fib(n - 2) }
print(fib(10))
`);
    }

    if (!(await fs.exists('/home/demo.js'))) {
      await fs.writeFile('/home/demo.js', `// JavaScript Demo
const fibonacci = (n) => {
  if (n <= 1) return n;
  return fibonacci(n - 1) + fibonacci(n - 2);
};

for (let i = 0; i <= 10; i++) {
  console.log(\`fib(\${i}) = \${fibonacci(i)}\`);
}
`);
    }

    if (!(await fs.exists('/home/demo.py'))) {
      await fs.writeFile('/home/demo.py', `# Python Demo
def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

for i in range(11):
    print(f"fib({i}) = {fibonacci(i)}")
`);
    }
  }

  _startClock() {
    const clockEl = document.getElementById('clock');
    const update = () => {
      const now = new Date();
      clockEl.textContent = now.toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit' });
    };
    update();
    this.clock = setInterval(update, 30000);
  }

  _bindLauncher() {
    document.querySelectorAll('.launcher-icon').forEach(icon => {
      icon.addEventListener('click', () => {
        const app = icon.dataset.app;
        this.launchApp(app);
      });
    });

    // 태스크바 시작 버튼
    document.getElementById('start-btn')?.addEventListener('click', () => {
      this._toggleStartMenu();
    });

    // 키보드 단축키
    document.addEventListener('keydown', (e) => {
      if (e.ctrlKey && e.key === 'e') { e.preventDefault(); this.launchApp('editor'); }
      if (e.ctrlKey && e.key === 'r') { e.preventDefault(); this.launchApp('repl'); }
      if (e.ctrlKey && e.key === 'f') { e.preventDefault(); this.launchApp('files'); }
      if (e.ctrlKey && e.key === 'g') { e.preventDefault(); this.launchApp('git'); }
      if (e.ctrlKey && e.key === 'i') { e.preventDefault(); this.launchApp('ai'); }
    });
  }

  async launchApp(appName, opts = {}) {
    switch (appName) {
      case 'editor':  return this._launchEditor(opts);
      case 'repl':    return this._launchREPL(opts);
      case 'files':   return this._launchFileManager();
      case 'git':     return this._launchGitViewer();
      case 'ai':      return this._launchAIPanel();
      case 'settings': return this._launchSettings();
      default:
        console.warn('[OS] Unknown app:', appName);
    }
  }

  // ─── 에디터 ─────────────────────────────────────────────────────

  async _launchEditor(opts = {}) {
    const path = opts.path ?? '/home/untitled.fl';
    const runtime = opts.runtime ?? runtimeManager.detectRuntime(path);

    // 이미 열려있으면 포커스
    if (this.openFiles.has(path)) {
      this.wm.focus(this.openFiles.get(path));
      return;
    }

    const content = document.createElement('div');
    content.className = 'app-editor';
    content.innerHTML = `
      <div class="editor-toolbar">
        <select class="runtime-select" title="런타임 선택">
          <option value="fv-lang" ${runtime === 'fv-lang' ? 'selected' : ''}>FV-Lang</option>
          <option value="javascript" ${runtime === 'javascript' ? 'selected' : ''}>JavaScript</option>
          <option value="python" ${runtime === 'python' ? 'selected' : ''}>Python</option>
        </select>
        <button class="btn-run" title="Ctrl+Enter">▶ 실행</button>
        <button class="btn-save" title="Ctrl+S">💾 저장</button>
        <span class="editor-status">준비</span>
      </div>
      <div class="editor-main">
        <div class="editor-pane"></div>
        <div class="editor-output">
          <div class="output-header">출력</div>
          <pre class="output-content"></pre>
        </div>
      </div>
    `;

    const winId = this.wm.createWindow({
      title: path.split('/').pop(),
      icon: this._fileIcon(path),
      width: 900,
      height: 600,
      content,
      app: null,
    });

    this.openFiles.set(path, winId);

    const editorPane = content.querySelector('.editor-pane');
    const outputEl = content.querySelector('.output-content');
    const statusEl = content.querySelector('.editor-status');
    const runtimeSelect = content.querySelector('.runtime-select');

    // 파일 내용 로드
    let fileContent = '';
    try {
      fileContent = await fs.readFile(path);
    } catch {
      fileContent = opts.initialContent ?? '';
    }

    let currentRuntime = runtime;

    const editor = new CodeEditor(editorPane, {
      runtime: currentRuntime,
      initialContent: fileContent,
      ai,
      onSave: async (code) => {
        await fs.writeFile(path, code);
        statusEl.textContent = '저장됨 ✓';
        setTimeout(() => statusEl.textContent = '준비', 2000);
      },
      onChange: () => {
        statusEl.textContent = '수정됨';
      },
    });

    const run = async () => {
      const code = editor.getValue();
      outputEl.textContent = '실행 중...';
      statusEl.textContent = '실행 중...';

      // Python 런타임 필요시 로드
      if (currentRuntime === 'python' && !runtimeManager.runtimes.has('python')) {
        outputEl.textContent = 'Python (Pyodide) 로딩 중... 잠시 기다려주세요';
      }

      const result = await runtimeManager.execute(code, currentRuntime);

      let out = '';
      if (result.stdout) out += result.stdout;
      if (result.stderr) out += (out ? '\n[stderr]\n' : '[stderr]\n') + result.stderr;
      if (!out) out = '(출력 없음)';
      out += `\n\n[${result.duration.toFixed(1)}ms]`;

      outputEl.textContent = out;
      outputEl.className = 'output-content' + (result.exitCode !== 0 ? ' output-error' : '');
      statusEl.textContent = result.exitCode === 0 ? '완료 ✓' : '오류 ✗';
    };

    content.querySelector('.btn-run').addEventListener('click', run);
    content.querySelector('.btn-save').addEventListener('click', () => {
      fs.writeFile(path, editor.getValue());
      statusEl.textContent = '저장됨 ✓';
      setTimeout(() => statusEl.textContent = '준비', 2000);
    });

    content.addEventListener('editor-run', (e) => run());

    runtimeSelect.addEventListener('change', (e) => {
      currentRuntime = e.target.value;
      editor.setRuntime(currentRuntime);
    });

    // 윈도우 닫힐 때 정리
    const originalClose = () => this.openFiles.delete(path);
    const winEntry = this.wm.windows.get(winId);
    if (winEntry) winEntry.config.app = { destroy: originalClose };

    return winId;
  }

  // ─── REPL ────────────────────────────────────────────────────────

  _launchREPL(opts = {}) {
    const content = document.createElement('div');
    content.className = 'app-repl';

    const defaultRuntime = opts.runtime ?? 'fv-lang';

    content.innerHTML = `
      <div class="repl-toolbar">
        <select class="repl-runtime">
          <option value="fv-lang">FV-Lang</option>
          <option value="javascript">JavaScript</option>
          <option value="python">Python (로드 필요)</option>
        </select>
        <button class="repl-clear">지우기</button>
        <button class="repl-history-btn">히스토리</button>
      </div>
      <div class="repl-output"></div>
      <div class="repl-input-row">
        <span class="repl-prompt">›</span>
        <input class="repl-input" type="text" placeholder="코드 입력 후 Enter..." autocomplete="off" spellcheck="false">
        <button class="repl-run-btn">실행</button>
      </div>
    `;

    const winId = this.wm.createWindow({
      title: 'REPL',
      icon: '⚡',
      width: 700,
      height: 450,
      content,
    });

    const outputEl = content.querySelector('.repl-output');
    const inputEl = content.querySelector('.repl-input');
    const runtimeSelect = content.querySelector('.repl-runtime');
    const promptEl = content.querySelector('.repl-prompt');

    runtimeSelect.value = defaultRuntime;

    let currentRuntime = defaultRuntime;
    let historyBuf = [];
    let histIdx = -1;

    const updatePrompt = () => {
      const prompts = { 'fv-lang': 'fl›', 'javascript': 'js›', 'python': 'py›' };
      promptEl.textContent = prompts[currentRuntime] ?? '›';
    };

    updatePrompt();
    runtimeSelect.addEventListener('change', (e) => {
      currentRuntime = e.target.value;
      updatePrompt();
    });

    const appendOutput = (type, text) => {
      const line = document.createElement('div');
      line.className = `repl-line repl-${type}`;

      if (type === 'input') {
        line.innerHTML = `<span class="repl-line-prompt">${promptEl.textContent}</span> <span class="repl-line-code">${this._escapeHtml(text)}</span>`;
      } else {
        line.textContent = text;
      }

      outputEl.appendChild(line);
      outputEl.scrollTop = outputEl.scrollHeight;
    };

    const runCode = async () => {
      const code = inputEl.value.trim();
      if (!code) return;

      historyBuf.unshift(code);
      histIdx = -1;
      inputEl.value = '';
      appendOutput('input', code);

      // DB에 히스토리 저장
      await fs.dbPut('repl-history', { runtime: currentRuntime, code, timestamp: Date.now() });

      if (currentRuntime === 'python' && !runtimeManager.runtimes.has('python')) {
        appendOutput('info', '⏳ Python 런타임 로딩 중... (최초 로드 시 1-2분 소요)');
      }

      const result = await runtimeManager.execute(code, currentRuntime);

      if (result.stdout) appendOutput('output', result.stdout);
      if (result.stderr) appendOutput('error', result.stderr);
      if (!result.stdout && !result.stderr) appendOutput('info', `(완료, ${result.duration.toFixed(1)}ms)`);
    };

    inputEl.addEventListener('keydown', async (e) => {
      if (e.key === 'Enter') {
        await runCode();
      } else if (e.key === 'ArrowUp') {
        histIdx = Math.min(histIdx + 1, historyBuf.length - 1);
        inputEl.value = historyBuf[histIdx] ?? '';
        e.preventDefault();
      } else if (e.key === 'ArrowDown') {
        histIdx = Math.max(histIdx - 1, -1);
        inputEl.value = histIdx >= 0 ? (historyBuf[histIdx] ?? '') : '';
        e.preventDefault();
      }
    });

    content.querySelector('.repl-run-btn').addEventListener('click', runCode);
    content.querySelector('.repl-clear').addEventListener('click', () => {
      outputEl.innerHTML = '';
    });

    // 환영 메시지
    appendOutput('info', `Personal Code OS REPL v1.0 — ${currentRuntime} 모드`);
    appendOutput('info', 'Ctrl+Enter: 에디터 실행 | Ctrl+I: AI 어시스턴트');

    setTimeout(() => inputEl.focus(), 100);
    return winId;
  }

  // ─── 파일 관리자 ─────────────────────────────────────────────────

  async _launchFileManager() {
    const content = document.createElement('div');
    content.className = 'app-files';
    content.innerHTML = `
      <div class="files-toolbar">
        <button class="btn-new-file">📄 새 파일</button>
        <button class="btn-new-dir">📁 새 폴더</button>
        <span class="files-path">/home</span>
      </div>
      <div class="files-list"></div>
    `;

    const winId = this.wm.createWindow({
      title: '파일 관리자',
      icon: '📁',
      width: 500,
      height: 400,
      content,
    });

    let currentPath = '/home';
    const listEl = content.querySelector('.files-list');
    const pathEl = content.querySelector('.files-path');

    const renderDir = async (path) => {
      currentPath = path;
      pathEl.textContent = path;
      listEl.innerHTML = '';

      // 상위 디렉토리
      if (path !== '/') {
        const upItem = document.createElement('div');
        upItem.className = 'file-item file-dir';
        upItem.innerHTML = '<span class="file-icon">📁</span> <span class="file-name">..</span>';
        upItem.addEventListener('click', () => {
          const parent = path.split('/').slice(0, -1).join('/') || '/';
          renderDir(parent);
        });
        listEl.appendChild(upItem);
      }

      const entries = await fs.readDir(path);
      entries.sort((a, b) => {
        if (a.type !== b.type) return a.type === 'dir' ? -1 : 1;
        return a.name.localeCompare(b.name);
      });

      for (const entry of entries) {
        const item = document.createElement('div');
        item.className = `file-item ${entry.type === 'dir' ? 'file-dir' : 'file-file'}`;
        const icon = entry.type === 'dir' ? '📁' : this._fileIcon(entry.name);
        const size = entry.type === 'file' ? ` (${this._formatSize(entry.size)})` : '';
        item.innerHTML = `<span class="file-icon">${icon}</span> <span class="file-name">${entry.name}</span><span class="file-meta">${size}</span>`;

        item.addEventListener('click', () => {
          if (entry.type === 'dir') {
            renderDir(entry.path);
          } else {
            this._launchEditor({ path: entry.path });
          }
        });

        // 우클릭 컨텍스트 메뉴
        item.addEventListener('contextmenu', (e) => {
          e.preventDefault();
          this._showContextMenu(e, [
            { label: '열기', action: () => this._launchEditor({ path: entry.path }) },
            { label: '삭제', action: async () => {
              if (confirm(`${entry.name}을 삭제하시겠습니까?`)) {
                await fs.unlink(entry.path);
                renderDir(currentPath);
              }
            }},
          ]);
        });

        listEl.appendChild(item);
      }
    };

    content.querySelector('.btn-new-file').addEventListener('click', async () => {
      const name = prompt('파일 이름:', 'new-file.fl');
      if (!name) return;
      const path = `${currentPath}/${name}`;
      await fs.writeFile(path, '');
      await renderDir(currentPath);
      this._launchEditor({ path });
    });

    content.querySelector('.btn-new-dir').addEventListener('click', async () => {
      const name = prompt('폴더 이름:', 'new-folder');
      if (!name) return;
      await fs.mkdir(`${currentPath}/${name}`);
      renderDir(currentPath);
    });

    await renderDir('/home');
    return winId;
  }

  // ─── Git 뷰어 ────────────────────────────────────────────────────

  async _launchGitViewer() {
    const content = document.createElement('div');
    content.className = 'app-git';
    content.innerHTML = `
      <div class="git-toolbar">
        <button class="git-commit-btn">💾 커밋</button>
        <button class="git-branch-btn">🌿 브랜치</button>
        <button class="git-status-btn">📊 상태</button>
      </div>
      <div class="git-panels">
        <div class="git-log">
          <div class="panel-title">커밋 히스토리</div>
          <div class="git-log-list"></div>
        </div>
        <div class="git-detail">
          <div class="panel-title">상세</div>
          <div class="git-detail-content"></div>
        </div>
      </div>
    `;

    const winId = this.wm.createWindow({
      title: 'Git Viewer',
      icon: '🌿',
      width: 750,
      height: 450,
      content,
    });

    const repo = new Repository('/home');
    await repo.init();
    this.activeRepo = repo;

    const logListEl = content.querySelector('.git-log-list');
    const detailEl = content.querySelector('.git-detail-content');

    const refreshLog = async () => {
      const commits = await repo.log();
      logListEl.innerHTML = '';

      if (commits.length === 0) {
        logListEl.innerHTML = '<div class="git-empty">커밋이 없습니다</div>';
        return;
      }

      for (const commit of commits) {
        const item = document.createElement('div');
        item.className = 'git-commit-item';
        const time = new Date(commit.timestamp).toLocaleString('ko-KR');
        item.innerHTML = `
          <div class="commit-hash">${commit.hash.slice(0, 7)}</div>
          <div class="commit-msg">${this._escapeHtml(commit.message)}</div>
          <div class="commit-meta">${commit.author} · ${time}</div>
        `;
        item.addEventListener('click', () => {
          detailEl.innerHTML = `
            <div><b>커밋:</b> ${commit.hash}</div>
            <div><b>작성자:</b> ${commit.author}</div>
            <div><b>시간:</b> ${time}</div>
            <div><b>트리:</b> ${commit.tree}</div>
            <div><b>메시지:</b><br>${this._escapeHtml(commit.message)}</div>
            ${commit.parent ? `<div><b>부모:</b> ${commit.parent.slice(0, 7)}</div>` : '<div><b>루트 커밋</b></div>'}
          `;
        });
        logListEl.appendChild(item);
      }
    };

    content.querySelector('.git-commit-btn').addEventListener('click', async () => {
      const message = prompt('커밋 메시지:', '');
      if (!message) return;
      try {
        const commit = await repo.commit(message, 'You');
        alert(`커밋 완료: ${commit.hash.slice(0, 7)}`);
        refreshLog();
      } catch (e) {
        alert(`오류: ${e.message}`);
      }
    });

    content.querySelector('.git-status-btn').addEventListener('click', async () => {
      const status = await repo.getStatus();
      detailEl.innerHTML = `
        <b>수정됨:</b> ${status.modified.join(', ') || '없음'}<br>
        <b>추가됨:</b> ${status.added.join(', ') || '없음'}<br>
        <b>삭제됨:</b> ${status.deleted.join(', ') || '없음'}
      `;
    });

    await refreshLog();
    return winId;
  }

  // ─── AI 패널 ─────────────────────────────────────────────────────

  _launchAIPanel() {
    const content = document.createElement('div');
    content.className = 'app-ai';
    content.innerHTML = `
      <div class="ai-header">
        <span class="ai-status-dot"></span>
        <span class="ai-status-text">AI 어시스턴트 (오프라인 모드)</span>
        <button class="ai-load-btn">🧠 모델 로드</button>
        <button class="ai-clear-btn">지우기</button>
      </div>
      <div class="ai-messages"></div>
      <div class="ai-input-row">
        <textarea class="ai-input" placeholder="AI에게 물어보세요... (코드 질문, 버그 수정, 설명 등)" rows="3"></textarea>
        <button class="ai-send-btn">전송</button>
      </div>
      <div class="ai-shortcuts">
        빠른 질문:
        <button class="ai-quick" data-q="FV-Lang 기본 문법 알려줘">FV-Lang 문법</button>
        <button class="ai-quick" data-q="재귀 함수 예시 보여줘">재귀 함수</button>
        <button class="ai-quick" data-q="고차 함수란 뭐야?">고차 함수</button>
      </div>
    `;

    const winId = this.wm.createWindow({
      title: 'AI 어시스턴트',
      icon: '🤖',
      width: 550,
      height: 500,
      content,
    });

    const messagesEl = content.querySelector('.ai-messages');
    const inputEl = content.querySelector('.ai-input');
    const statusDot = content.querySelector('.ai-status-dot');
    const statusText = content.querySelector('.ai-status-text');

    const appendMsg = (role, text) => {
      const msg = document.createElement('div');
      msg.className = `ai-msg ai-msg-${role}`;
      msg.innerHTML = `
        <div class="ai-msg-role">${role === 'user' ? '나' : '🤖 AI'}</div>
        <div class="ai-msg-content">${this._escapeHtml(text).replace(/```(\w*)\n?([\s\S]*?)```/g,
          (_, lang, code) => `<pre class="ai-code">${code}</pre>`)}</div>
      `;
      messagesEl.appendChild(msg);
      messagesEl.scrollTop = messagesEl.scrollHeight;
    };

    const send = async () => {
      const text = inputEl.value.trim();
      if (!text) return;
      inputEl.value = '';
      appendMsg('user', text);

      // 규칙 기반 폴백 먼저
      const ruleRes = ai.constructor.getRuleBasedResponse(text);
      if (ruleRes) {
        appendMsg('assistant', ruleRes);
        return;
      }

      if (ai.status !== 'ready') {
        appendMsg('assistant', '⚠️ AI 모델이 로드되지 않았습니다. 상단의 "모델 로드" 버튼을 눌러주세요.\n\n(오프라인에서는 FV-Lang, Python, JavaScript 관련 기본 질문에 답할 수 있습니다)');
        return;
      }

      const typing = document.createElement('div');
      typing.className = 'ai-msg ai-msg-assistant ai-typing';
      typing.textContent = 'AI 응답 생성 중...';
      messagesEl.appendChild(typing);

      const result = await ai.chat(text, { stream: false });
      typing.remove();
      appendMsg('assistant', result.content);
    };

    content.querySelector('.ai-send-btn').addEventListener('click', send);
    inputEl.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); }
    });

    content.querySelector('.ai-load-btn').addEventListener('click', async () => {
      statusText.textContent = '모델 로딩 중... (최초 로드 시 수백MB 다운로드)';
      statusDot.style.background = 'orange';

      ai.on('progress', ({ progress, text }) => {
        statusText.textContent = `${text} (${Math.round(progress * 100)}%)`;
      });

      try {
        await ai.loadModel();
        statusDot.style.background = 'lime';
        statusText.textContent = `${ai.model} 준비됨`;
        appendMsg('assistant', '✅ AI 모델이 로드되었습니다! 이제 코드 질문, 버그 수정, 자동완성 등을 사용할 수 있습니다.');
      } catch (e) {
        statusDot.style.background = 'red';
        statusText.textContent = `로드 실패: ${e.message}`;
        appendMsg('assistant', `❌ 모델 로드 실패: ${e.message}\n\n인터넷 연결을 확인하거나, 브라우저가 WebGPU를 지원하는지 확인해주세요.`);
      }
    });

    content.querySelector('.ai-clear-btn').addEventListener('click', () => {
      messagesEl.innerHTML = '';
      ai.clearHistory();
    });

    content.querySelectorAll('.ai-quick').forEach(btn => {
      btn.addEventListener('click', () => {
        inputEl.value = btn.dataset.q;
        send();
      });
    });

    // 환영 메시지
    appendMsg('assistant', '안녕하세요! Personal Code OS AI 어시스턴트입니다.\n\nFV-Lang, Python, JavaScript 코드 관련 질문을 해주세요.\n로컬 LLM 사용 시 "모델 로드" 버튼을 클릭하세요 (오프라인 동작).');

    return winId;
  }

  // ─── 설정 ─────────────────────────────────────────────────────────

  _launchSettings() {
    const content = document.createElement('div');
    content.className = 'app-settings';
    content.innerHTML = `
      <div class="settings-section">
        <h3>에디터</h3>
        <label>폰트 크기: <input type="range" id="font-size" min="10" max="24" value="14"> <span id="font-size-val">14px</span></label>
        <label>탭 크기: <select id="tab-size">
          <option value="2">2 스페이스</option>
          <option value="4">4 스페이스</option>
        </select></label>
      </div>
      <div class="settings-section">
        <h3>저장소 정보</h3>
        <button id="storage-info-btn">저장소 사용량 확인</button>
        <pre id="storage-info"></pre>
      </div>
      <div class="settings-section">
        <h3>런타임</h3>
        <div id="runtime-list"></div>
      </div>
    `;

    const winId = this.wm.createWindow({
      title: '설정',
      icon: '⚙️',
      width: 400,
      height: 450,
      content,
    });

    content.querySelector('#storage-info-btn').addEventListener('click', async () => {
      if ('storage' in navigator) {
        const estimate = await navigator.storage.estimate();
        content.querySelector('#storage-info').textContent =
          `사용: ${this._formatSize(estimate.usage ?? 0)}\n` +
          `할당: ${this._formatSize(estimate.quota ?? 0)}\n` +
          `OPFS: ${'getDirectory' in navigator.storage ? '지원' : '미지원'}`;
      }
    });

    const rtList = content.querySelector('#runtime-list');
    runtimeManager.getLoadedRuntimes().forEach(rt => {
      const el = document.createElement('div');
      el.textContent = `${rt.name}: ${rt.version} (${rt.status})`;
      rtList.appendChild(el);
    });

    return winId;
  }

  // ─── 컨텍스트 메뉴 ──────────────────────────────────────────────

  _showContextMenu(e, items) {
    document.querySelector('.context-menu')?.remove();
    const menu = document.createElement('div');
    menu.className = 'context-menu';
    menu.style.cssText = `left:${e.clientX}px;top:${e.clientY}px;`;

    for (const item of items) {
      const el = document.createElement('div');
      el.className = 'context-item';
      el.textContent = item.label;
      el.addEventListener('click', () => { menu.remove(); item.action(); });
      menu.appendChild(el);
    }

    document.body.appendChild(menu);
    setTimeout(() => document.addEventListener('click', () => menu.remove(), { once: true }), 50);
  }

  // ─── 유틸 ────────────────────────────────────────────────────────

  _fileIcon(name) {
    const ext = name.split('.').pop()?.toLowerCase();
    const icons = { fl: '⚡', fv: '⚡', js: '💛', py: '🐍', c: '⚙️', h: '⚙️', md: '📝', json: '📋', txt: '📄' };
    return icons[ext] ?? '📄';
  }

  _formatSize(bytes) {
    if (bytes < 1024) return `${bytes}B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)}KB`;
    return `${(bytes / 1024 / 1024).toFixed(1)}MB`;
  }

  _escapeHtml(str) {
    return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  async _showWelcome() {
    const content = document.createElement('div');
    content.className = 'app-welcome';
    content.innerHTML = `
      <div class="welcome-logo">🖥️</div>
      <h2>Personal Code OS</h2>
      <p>브라우저 기반 완전 Self-Hosted 개발 환경</p>
      <div class="welcome-features">
        <div class="feature-item">⚡ FV-Lang REPL</div>
        <div class="feature-item">🐍 Python (Pyodide)</div>
        <div class="feature-item">💛 JavaScript</div>
        <div class="feature-item">🌿 Git VCS</div>
        <div class="feature-item">🤖 로컬 AI</div>
        <div class="feature-item">💾 OPFS 저장소</div>
      </div>
      <div class="welcome-shortcuts">
        <b>단축키</b><br>
        Ctrl+E: 에디터 | Ctrl+R: REPL | Ctrl+F: 파일관리자<br>
        Ctrl+G: Git | Ctrl+I: AI 어시스턴트
      </div>
      <div class="welcome-actions">
        <button onclick="document.querySelector('.os-window').querySelector('.btn-close')?.click(); window.os.launchApp('editor')">에디터 열기</button>
        <button onclick="window.os.launchApp('repl')">REPL 시작</button>
        <button onclick="window.os.launchApp('files')">파일 관리자</button>
      </div>
    `;

    this.wm.createWindow({
      title: '시작하기',
      icon: '🏠',
      width: 500,
      height: 450,
      x: 200,
      y: 50,
      resizable: false,
      content,
    });
  }

  _toggleStartMenu() {
    let menu = document.querySelector('.start-menu');
    if (menu) { menu.remove(); return; }

    menu = document.createElement('div');
    menu.className = 'start-menu';
    menu.innerHTML = `
      <div class="start-menu-title">🖥️ Personal Code OS</div>
      <div class="start-menu-item" data-app="editor">📝 코드 에디터</div>
      <div class="start-menu-item" data-app="repl">⚡ REPL</div>
      <div class="start-menu-item" data-app="files">📁 파일 관리자</div>
      <div class="start-menu-item" data-app="git">🌿 Git 뷰어</div>
      <div class="start-menu-item" data-app="ai">🤖 AI 어시스턴트</div>
      <hr>
      <div class="start-menu-item" data-app="settings">⚙️ 설정</div>
    `;

    menu.querySelectorAll('.start-menu-item[data-app]').forEach(item => {
      item.addEventListener('click', () => { menu.remove(); this.launchApp(item.dataset.app); });
    });

    document.body.appendChild(menu);
    setTimeout(() => document.addEventListener('click', () => menu.remove(), { once: true }), 50);
  }
}

// 부팅
window.addEventListener('DOMContentLoaded', async () => {
  const os = new PersonalCodeOS();
  window.os = os;
  await os.boot();
});

toolUseResult.content:
/**
 * PersonalCodeOS - Main Application
 * 모든 서브시스템을 연결하는 최상위 오케스트레이터
 */

import { WindowManager } from './shell/window-manager.js';
import { fs } from './storage/fs.js';
import { Repository } from './vcs/repo.js';
import { runtimeManager } from './runtimes/manager.js';
import { ai } from './ai/assistant.js';
import { CodeEditor } from './editor/editor.js';

class PersonalCodeOS {
  constructor() {
    this.wm = null;
    this.openFiles = new Map(); // path → windowId
    this.activeRepo = null;
    this.clock = null;
  }

  async boot() {
    console.log('[OS] Booting Personal Code OS...');

    const desktop = document.getElementById('desktop');
    this.wm = new WindowManager(desktop);

    await fs.ready();
    console.log('[OS] Storage ready');

    // 기본 디렉토리 구조 생성
    await this._initDefaultFS();

    // 시계
    this._startClock();

    // 런처 아이콘 이벤트
    this._bindLauncher();

    // 시작 화면
    await this._showWelcome();

    console.log('[OS] Boot complete');
  }

  async _initDefaultFS() {
    const dirs = ['/home', '/home/projects', '/home/snippets', '/home/notes'];
    for (const dir of dirs) {
      if (!(await fs.exists(dir))) {
        await fs.mkdir(dir);
      }
    }

    // 기본 예제 파일
    if (!(await fs.exists('/home/hello.fl'))) {
      await fs.writeFile('/home/hello.fl', `# FV-Lang Hello World
fn greet(name) = "Hello, " + name

let msg = greet("Personal Code OS")
print(msg)

# 피보나치
fn fib(n) = if n <= 1 { n } else { fib(n - 1) + fib(n - 2) }
print(fib(10))
`);
    }

    if (!(await fs.exists('/home/demo.js'))) {
      await fs.writeFile('/home/demo.js', `// JavaScript Demo
const fibonacci = (n) => {
  if (n <= 1) return n;
  return fibonacci(n - 1) + fibonacci(n - 2);
};

for (let i = 0; i <= 10; i++) {
  console.log(\`fib(\${i}) = \${fibonacci(i)}\`);
}
`);
    }

    if (!(await fs.exists('/home/demo.py'))) {
      await fs.writeFile('/home/demo.py', `# Python Demo
def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

for i in range(11):
    print(f"fib({i}) = {fibonacci(i)}")
`);
    }
  }

  _startClock() {
    const clockEl = document.getElementById('clock');
    const update = () => {
      const now = new Date();
      clockEl.textContent = now.toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit' });
    };
    update();
    this.clock = setInterval(update, 30000);
  }

  _bindLauncher() {
    document.querySelectorAll('.launcher-icon').forEach(icon => {
      icon.addEventListener('click', () => {
        const app = icon.dataset.app;
        this.launchApp(app);
      });
    });

    // 태스크바 시작 버튼
    document.getElementById('start-btn')?.addEventListener('click', () => {
      this._toggleStartMenu();
    });

    // 키보드 단축키
    document.addEventListener('keydown', (e) => {
      if (e.ctrlKey && e.key === 'e') { e.preventDefault(); this.launchApp('editor'); }
      if (e.ctrlKey && e.key === 'r') { e.preventDefault(); this.launchApp('repl'); }
      if (e.ctrlKey && e.key === 'f') { e.preventDefault(); this.launchApp('files'); }
      if (e.ctrlKey && e.key === 'g') { e.preventDefault(); this.launchApp('git'); }
      if (e.ctrlKey && e.key === 'i') { e.preventDefault(); this.launchApp('ai'); }
    });
  }

  async launchApp(appName, opts = {}) {
    switch (appName) {
      case 'editor':  return this._launchEditor(opts);
      case 'repl':    return this._launchREPL(opts);
      case 'files':   return this._launchFileManager();
      case 'git':     return this._launchGitViewer();
      case 'ai':      return this._launchAIPanel();
      case 'settings': return this._launchSettings();
      default:
        console.warn('[OS] Unknown app:', appName);
    }
  }

  // ─── 에디터 ─────────────────────────────────────────────────────

  async _launchEditor(opts = {}) {
    const path = opts.path ?? '/home/untitled.fl';
    const runtime = opts.runtime ?? runtimeManager.detectRuntime(path);

    // 이미 열려있으면 포커스
    if (this.openFiles.has(path)) {
      this.wm.focus(this.openFiles.get(path));
      return;
    }

    const content = document.createElement('div');
    content.className = 'app-editor';
    content.innerHTML = `
      <div class="editor-toolbar">
        <select class="runtime-select" title="런타임 선택">
          <option value="fv-lang" ${runtime === 'fv-lang' ? 'selected' : ''}>FV-Lang</option>
          <option value="javascript" ${runtime === 'javascript' ? 'selected' : ''}>JavaScript</option>
          <option value="python" ${runtime === 'python' ? 'selected' : ''}>Python</option>
        </select>
        <button class="btn-run" title="Ctrl+Enter">▶ 실행</button>
        <button class="btn-save" title="Ctrl+S">💾 저장</button>
        <span class="editor-status">준비</span>
      </div>
      <div class="editor-main">
        <div class="editor-pane"></div>
        <div class="editor-output">
          <div class="output-header">출력</div>
          <pre class="output-content"></pre>
        </div>
      </div>
    `;

    const winId = this.wm.createWindow({
      title: path.split('/').pop(),
      icon: this._fileIcon(path),
      width: 900,
      height: 600,
      content,
      app: null,
    });

    this.openFiles.set(path, winId);

    const editorPane = content.querySelector('.editor-pane');
    const outputEl = content.querySelector('.output-content');
    const statusEl = content.querySelector('.editor-status');
    const runtimeSelect = content.querySelector('.runtime-select');

    // 파일 내용 로드
    let fileContent = '';
    try {
      fileContent = await fs.readFile(path);
    } catch {
      fileContent = opts.initialContent ?? '';
    }

    let currentRuntime = runtime;

    const editor = new CodeEditor(editorPane, {
      runtime: currentRuntime,
      initialContent: fileContent,
      ai,
      onSave: async (code) => {
        await fs.writeFile(path, code);
        statusEl.textContent = '저장됨 ✓';
        setTimeout(() => statusEl.textContent = '준비', 2000);
      },
      onChange: () => {
        statusEl.textContent = '수정됨';
      },
    });

    const run = async () => {
      const code = editor.getValue();
      outputEl.textContent = '실행 중...';
      statusEl.textContent = '실행 중...';

      // Python 런타임 필요시 로드
      if (currentRuntime === 'python' && !runtimeManager.runtimes.has('python')) {
        outputEl.textContent = 'Python (Pyodide) 로딩 중... 잠시 기다려주세요';
      }

      const result = await runtimeManager.execute(code, currentRuntime);

      let out = '';
      if (result.stdout) out += result.stdout;
      if (result.stderr) out += (out ? '\n[stderr]\n' : '[stderr]\n') + result.stderr;
      if (!out) out = '(출력 없음)';
      out += `\n\n[${result.duration.toFixed(1)}ms]`;

      outputEl.textContent = out;
      outputEl.className = 'output-content' + (result.exitCode !== 0 ? ' output-error' : '');
      statusEl.textContent = result.exitCode === 0 ? '완료 ✓' : '오류 ✗';
    };

    content.querySelector('.btn-run').addEventListener('click', run);
    content.querySelector('.btn-save').addEventListener('click', () => {
      fs.writeFile(path, editor.getValue());
      statusEl.textContent = '저장됨 ✓';
      setTimeout(() => statusEl.textContent = '준비', 2000);
    });

    content.addEventListener('editor-run', (e) => run());

    runtimeSelect.addEventListener('change', (e) => {
      currentRuntime = e.target.value;
      editor.setRuntime(currentRuntime);
    });

    // 윈도우 닫힐 때 정리
    const originalClose = () => this.openFiles.delete(path);
    const winEntry = this.wm.windows.get(winId);
    if (winEntry) winEntry.config.app = { destroy: originalClose };

    return winId;
  }

  // ─── REPL ────────────────────────────────────────────────────────

  _launchREPL(opts = {}) {
    const content = document.createElement('div');
    content.className = 'app-repl';

    const defaultRuntime = opts.runtime ?? 'fv-lang';

    content.innerHTML = `
      <div class="repl-toolbar">
        <select class="repl-runtime">
          <option value="fv-lang">FV-Lang</option>
          <option value="javascript">JavaScript</option>
          <option value="python">Python (로드 필요)</option>
        </select>
        <button class="repl-clear">지우기</button>
        <button class="repl-history-btn">히스토리</button>
      </div>
      <div class="repl-output"></div>
      <div class="repl-input-row">
        <span class="repl-prompt">›</span>
        <input class="repl-input" type="text" placeholder="코드 입력 후 Enter..." autocomplete="off" spellcheck="false">
        <button class="repl-run-btn">실행</button>
      </div>
    `;

    const winId = this.wm.createWindow({
      title: 'REPL',
      icon: '⚡',
      width: 700,
      height: 450,
      content,
    });

    const outputEl = content.querySelector('.repl-output');
    const inputEl = content.querySelector('.repl-input');
    const runtimeSelect = content.querySelector('.repl-runtime');
    const promptEl = content.querySelector('.repl-prompt');

    runtimeSelect.value = defaultRuntime;

    let currentRuntime = defaultRuntime;
    let historyBuf = [];
    let histIdx = -1;

    const updatePrompt = () => {
      const prompts = { 'fv-lang': 'fl›', 'javascript': 'js›', 'python': 'py›' };
      promptEl.textContent = prompts[currentRuntime] ?? '›';
    };

    updatePrompt();
    runtimeSelect.addEventListener('change', (e) => {
      currentRuntime = e.target.value;
      updatePrompt();
    });

    const appendOutput = (type, text) => {
      const line = document.createElement('div');
      line.className = `repl-line repl-${type}`;

      if (type === 'input') {
        line.innerHTML = `<span class="repl-line-prompt">${promptEl.textContent}</span> <span class="repl-line-code">${this._escapeHtml(text)}</span>`;
      } else {
        line.textContent = text;
      }

      outputEl.appendChild(line);
      outputEl.scrollTop = outputEl.scrollHeight;
    };

    const runCode = async () => {
      const code = inputEl.value.trim();
      if (!code) return;

      historyBuf.unshift(code);
      histIdx = -1;
      inputEl.value = '';
      appendOutput('input', code);

      // DB에 히스토리 저장
      await fs.dbPut('repl-history', { runtime: currentRuntime, code, timestamp: Date.now() });

      if (currentRuntime === 'python' && !runtimeManager.runtimes.has('python')) {
        appendOutput('info', '⏳ Python 런타임 로딩 중... (최초 로드 시 1-2분 소요)');
      }

      const result = await runtimeManager.execute(code, currentRuntime);

      if (result.stdout) appendOutput('output', result.stdout);
      if (result.stderr) appendOutput('error', result.stderr);
      if (!result.stdout && !result.stderr) appendOutput('info', `(완료, ${result.duration.toFixed(1)}ms)`);
    };

    inputEl.addEventListener('keydown', async (e) => {
      if (e.key === 'Enter') {
        await runCode();
      } else if (e.key === 'ArrowUp') {
        histIdx = Math.min(histIdx + 1, historyBuf.length - 1);
        inputEl.value = historyBuf[histIdx] ?? '';
        e.preventDefault();
      } else if (e.key === 'ArrowDown') {
        histIdx = Math.max(histIdx - 1, -1);
        inputEl.value = histIdx >= 0 ? (historyBuf[histIdx] ?? '') : '';
        e.preventDefault();
      }
    });

    content.querySelector('.repl-run-btn').addEventListener('click', runCode);
    content.querySelector('.repl-clear').addEventListener('click', () => {
      outputEl.innerHTML = '';
    });

    // 환영 메시지
    appendOutput('info', `Personal Code OS REPL v1.0 — ${currentRuntime} 모드`);
    appendOutput('info', 'Ctrl+Enter: 에디터 실행 | Ctrl+I: AI 어시스턴트');

    setTimeout(() => inputEl.focus(), 100);
    return winId;
  }

  // ─── 파일 관리자 ─────────────────────────────────────────────────

  async _launchFileManager() {
    const content = document.createElement('div');
    content.className = 'app-files';
    content.innerHTML = `
      <div class="files-toolbar">
        <button class="btn-new-file">📄 새 파일</button>
        <button class="btn-new-dir">📁 새 폴더</button>
        <span class="files-path">/home</span>
      </div>
      <div class="files-list"></div>
    `;

    const winId = this.wm.createWindow({
      title: '파일 관리자',
      icon: '📁',
      width: 500,
      height: 400,
      content,
    });

    let currentPath = '/home';
    const listEl = content.querySelector('.files-list');
    const pathEl = content.querySelector('.files-path');

    const renderDir = async (path) => {
      currentPath = path;
      pathEl.textContent = path;
      listEl.innerHTML = '';

      // 상위 디렉토리
      if (path !== '/') {
        const upItem = document.createElement('div');
        upItem.className = 'file-item file-dir';
        upItem.innerHTML = '<span class="file-icon">📁</span> <span class="file-name">..</span>';
        upItem.addEventListener('click', () => {
          const parent = path.split('/').slice(0, -1).join('/') || '/';
          renderDir(parent);
        });
        listEl.appendChild(upItem);
      }

      const entries = await fs.readDir(path);
      entries.sort((a, b) => {
        if (a.type !== b.type) return a.type === 'dir' ? -1 : 1;
        return a.name.localeCompare(b.name);
      });

      for (const entry of entries) {
        const item = document.createElement('div');
        item.className = `file-item ${entry.type === 'dir' ? 'file-dir' : 'file-file'}`;
        const icon = entry.type === 'dir' ? '📁' : this._fileIcon(entry.name);
        const size = entry.type === 'file' ? ` (${this._formatSize(entry.size)})` : '';
        item.innerHTML = `<span class="file-icon">${icon}</span> <span class="file-name">${entry.name}</span><span class="file-meta">${size}</span>`;

        item.addEventListener('click', () => {
          if (entry.type === 'dir') {
            renderDir(entry.path);
          } else {
            this._launchEditor({ path: entry.path });
          }
        });

        // 우클릭 컨텍스트 메뉴
        item.addEventListener('contextmenu', (e) => {
          e.preventDefault();
          this._showContextMenu(e, [
            { label: '열기', action: () => this._launchEditor({ path: entry.path }) },
            { label: '삭제', action: async () => {
              if (confirm(`${entry.name}을 삭제하시겠습니까?`)) {
                await fs.unlink(entry.path);
                renderDir(currentPath);
              }
            }},
          ]);
        });

        listEl.appendChild(item);
      }
    };

    content.querySelector('.btn-new-file').addEventListener('click', async () => {
      const name = prompt('파일 이름:', 'new-file.fl');
      if (!name) return;
      const path = `${currentPath}/${name}`;
      await fs.writeFile(path, '');
      await renderDir(currentPath);
      this._launchEditor({ path });
    });

    content.querySelector('.btn-new-dir').addEventListener('click', async () => {
      const name = prompt('폴더 이름:', 'new-folder');
      if (!name) return;
      await fs.mkdir(`${currentPath}/${name}`);
      renderDir(currentPath);
    });

    await renderDir('/home');
    return winId;
  }

  // ─── Git 뷰어 ────────────────────────────────────────────────────

  async _launchGitViewer() {
    const content = document.createElement('div');
    content.className = 'app-git';
    content.innerHTML = `
      <div class="git-toolbar">
        <button class="git-commit-btn">💾 커밋</button>
        <button class="git-branch-btn">🌿 브랜치</button>
        <button class="git-status-btn">📊 상태</button>
      </div>
      <div class="git-panels">
        <div class="git-log">
          <div class="panel-title">커밋 히스토리</div>
          <div class="git-log-list"></div>
        </div>
        <div class="git-detail">
          <div class="panel-title">상세</div>
          <div class="git-detail-content"></div>
        </div>
      </div>
    `;

    const winId = this.wm.createWindow({
      title: 'Git Viewer',
      icon: '🌿',
      width: 750,
      height: 450,
      content,
    });

    const repo = new Repository('/home');
    await repo.init();
    this.activeRepo = repo;

    const logListEl = content.querySelector('.git-log-list');
    const detailEl = content.querySelector('.git-detail-content');

    const refreshLog = async () => {
      const commits = await repo.log();
      logListEl.innerHTML = '';

      if (commits.length === 0) {
        logListEl.innerHTML = '<div class="git-empty">커밋이 없습니다</div>';
        return;
      }

      for (const commit of commits) {
        const item = document.createElement('div');
        item.className = 'git-commit-item';
        const time = new Date(commit.timestamp).toLocaleString('ko-KR');
        item.innerHTML = `
          <div class="commit-hash">${commit.hash.slice(0, 7)}</div>
          <div class="commit-msg">${this._escapeHtml(commit.message)}</div>
          <div class="commit-meta">${commit.author} · ${time}</div>
        `;
        item.addEventListener('click', () => {
          detailEl.innerHTML = `
            <div><b>커밋:</b> ${commit.hash}</div>
            <div><b>작성자:</b> ${commit.author}</div>
            <div><b>시간:</b> ${time}</div>
            <div><b>트리:</b> ${commit.tree}</div>
            <div><b>메시지:</b><br>${this._escapeHtml(commit.message)}</div>
            ${commit.parent ? `<div><b>부모:</b> ${commit.parent.slice(0, 7)}</div>` : '<div><b>루트 커밋</b></div>'}
          `;
        });
        logListEl.appendChild(item);
      }
    };

    content.querySelector('.git-commit-btn').addEventListener('click', async () => {
      const message = prompt('커밋 메시지:', '');
      if (!message) return;
      try {
        const commit = await repo.commit(message, 'You');
        alert(`커밋 완료: ${commit.hash.slice(0, 7)}`);
        refreshLog();
      } catch (e) {
        alert(`오류: ${e.message}`);
      }
    });

    content.querySelector('.git-status-btn').addEventListener('click', async () => {
      const status = await repo.getStatus();
      detailEl.innerHTML = `
        <b>수정됨:</b> ${status.modified.join(', ') || '없음'}<br>
        <b>추가됨:</b> ${status.added.join(', ') || '없음'}<br>
        <b>삭제됨:</b> ${status.deleted.join(', ') || '없음'}
      `;
    });

    await refreshLog();
    return winId;
  }

  // ─── AI 패널 ─────────────────────────────────────────────────────

  _launchAIPanel() {
    const content = document.createElement('div');
    content.className = 'app-ai';
    content.innerHTML = `
      <div class="ai-header">
        <span class="ai-status-dot"></span>
        <span class="ai-status-text">AI 어시스턴트 (오프라인 모드)</span>
        <button class="ai-load-btn">🧠 모델 로드</button>
        <button class="ai-clear-btn">지우기</button>
      </div>
      <div class="ai-messages"></div>
      <div class="ai-input-row">
        <textarea class="ai-input" placeholder="AI에게 물어보세요... (코드 질문, 버그 수정, 설명 등)" rows="3"></textarea>
        <button class="ai-send-btn">전송</button>
      </div>
      <div class="ai-shortcuts">
        빠른 질문:
        <button class="ai-quick" data-q="FV-Lang 기본 문법 알려줘">FV-Lang 문법</button>
        <button class="ai-quick" data-q="재귀 함수 예시 보여줘">재귀 함수</button>
        <button class="ai-quick" data-q="고차 함수란 뭐야?">고차 함수</button>
      </div>
    `;

    const winId = this.wm.createWindow({
      title: 'AI 어시스턴트',
      icon: '🤖',
      width: 550,
      height: 500,
      content,
    });

    const messagesEl = content.querySelector('.ai-messages');
    const inputEl = content.querySelector('.ai-input');
    const statusDot = content.querySelector('.ai-status-dot');
    const statusText = content.querySelector('.ai-status-text');

    const appendMsg = (role, text) => {
      const msg = document.createElement('div');
      msg.className = `ai-msg ai-msg-${role}`;
      msg.innerHTML = `
        <div class="ai-msg-role">${role === 'user' ? '나' : '🤖 AI'}</div>
        <div class="ai-msg-content">${this._escapeHtml(text).replace(/```(\w*)\n?([\s\S]*?)```/g,
          (_, lang, code) => `<pre class="ai-code">${code}</pre>`)}</div>
      `;
      messagesEl.appendChild(msg);
      messagesEl.scrollTop = messagesEl.scrollHeight;
    };

    const send = async () => {
      const text = inputEl.value.trim();
      if (!text) return;
      inputEl.value = '';
      appendMsg('user', text);

      // 규칙 기반 폴백 먼저
      const ruleRes = ai.constructor.getRuleBasedResponse(text);
      if (ruleRes) {
        appendMsg('assistant', ruleRes);
        return;
      }

      if (ai.status !== 'ready') {
        appendMsg('assistant', '⚠️ AI 모델이 로드되지 않았습니다. 상단의 "모델 로드" 버튼을 눌러주세요.\n\n(오프라인에서는 FV-Lang, Python, JavaScript 관련 기본 질문에 답할 수 있습니다)');
        return;
      }

      const typing = document.createElement('div');
      typing.className = 'ai-msg ai-msg-assistant ai-typing';
      typing.textContent = 'AI 응답 생성 중...';
      messagesEl.appendChild(typing);

      const result = await ai.chat(text, { stream: false });
      typing.remove();
      appendMsg('assistant', result.content);
    };

    content.querySelector('.ai-send-btn').addEventListener('click', send);
    inputEl.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); }
    });

    content.querySelector('.ai-load-btn').addEventListener('click', async () => {
      statusText.textContent = '모델 로딩 중... (최초 로드 시 수백MB 다운로드)';
      statusDot.style.background = 'orange';

      ai.on('progress', ({ progress, text }) => {
        statusText.textContent = `${text} (${Math.round(progress * 100)}%)`;
      });

      try {
        await ai.loadModel();
        statusDot.style.background = 'lime';
        statusText.textContent = `${ai.model} 준비됨`;
        appendMsg('assistant', '✅ AI 모델이 로드되었습니다! 이제 코드 질문, 버그 수정, 자동완성 등을 사용할 수 있습니다.');
      } catch (e) {
        statusDot.style.background = 'red';
        statusText.textContent = `로드 실패: ${e.message}`;
        appendMsg('assistant', `❌ 모델 로드 실패: ${e.message}\n\n인터넷 연결을 확인하거나, 브라우저가 WebGPU를 지원하는지 확인해주세요.`);
      }
    });

    content.querySelector('.ai-clear-btn').addEventListener('click', () => {
      messagesEl.innerHTML = '';
      ai.clearHistory();
    });

    content.querySelectorAll('.ai-quick').forEach(btn => {
      btn.addEventListener('click', () => {
        inputEl.value = btn.dataset.q;
        send();
      });
    });

    // 환영 메시지
    appendMsg('assistant', '안녕하세요! Personal Code OS AI 어시스턴트입니다.\n\nFV-Lang, Python, JavaScript 코드 관련 질문을 해주세요.\n로컬 LLM 사용 시 "모델 로드" 버튼을 클릭하세요 (오프라인 동작).');

    return winId;
  }

  // ─── 설정 ─────────────────────────────────────────────────────────

  _launchSettings() {
    const content = document.createElement('div');
    content.className = 'app-settings';
    content.innerHTML = `
      <div class="settings-section">
        <h3>에디터</h3>
        <label>폰트 크기: <input type="range" id="font-size" min="10" max="24" value="14"> <span id="font-size-val">14px</span></label>
        <label>탭 크기: <select id="tab-size">
          <option value="2">2 스페이스</option>
          <option value="4">4 스페이스</option>
        </select></label>
      </div>
      <div class="settings-section">
        <h3>저장소 정보</h3>
        <button id="storage-info-btn">저장소 사용량 확인</button>
        <pre id="storage-info"></pre>
      </div>
      <div class="settings-section">
        <h3>런타임</h3>
        <div id="runtime-list"></div>
      </div>
    `;

    const winId = this.wm.createWindow({
      title: '설정',
      icon: '⚙️',
      width: 400,
      height: 450,
      content,
    });

    content.querySelector('#storage-info-btn').addEventListener('click', async () => {
      if ('storage' in navigator) {
        const estimate = await navigator.storage.estimate();
        content.querySelector('#storage-info').textContent =
          `사용: ${this._formatSize(estimate.usage ?? 0)}\n` +
          `할당: ${this._formatSize(estimate.quota ?? 0)}\n` +
          `OPFS: ${'getDirectory' in navigator.storage ? '지원' : '미지원'}`;
      }
    });

    const rtList = content.querySelector('#runtime-list');
    runtimeManager.getLoadedRuntimes().forEach(rt => {
      const el = document.createElement('div');
      el.textContent = `${rt.name}: ${rt.version} (${rt.status})`;
      rtList.appendChild(el);
    });

    return winId;
  }

  // ─── 컨텍스트 메뉴 ──────────────────────────────────────────────

  _showContextMenu(e, items) {
    document.querySelector('.context-menu')?.remove();
    const menu = document.createElement('div');
    menu.className = 'context-menu';
    menu.style.cssText = `left:${e.clientX}px;top:${e.clientY}px;`;

    for (const item of items) {
      const el = document.createElement('div');
      el.className = 'context-item';
      el.textContent = item.label;
      el.addEventListener('click', () => { menu.remove(); item.action(); });
      menu.appendChild(el);
    }

    document.body.appendChild(menu);
    setTimeout(() => document.addEventListener('click', () => menu.remove(), { once: true }), 50);
  }

  // ─── 유틸 ────────────────────────────────────────────────────────

  _fileIcon(name) {
    const ext = name.split('.').pop()?.toLowerCase();
    const icons = { fl: '⚡', fv: '⚡', js: '💛', py: '🐍', c: '⚙️', h: '⚙️', md: '📝', json: '📋', txt: '📄' };
    return icons[ext] ?? '📄';
  }

  _formatSize(bytes) {
    if (bytes < 1024) return `${bytes}B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)}KB`;
    return `${(bytes / 1024 / 1024).toFixed(1)}MB`;
  }

  _escapeHtml(str) {
    return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  async _showWelcome() {
    const content = document.createElement('div');
    content.className = 'app-welcome';
    content.innerHTML = `
      <div class="welcome-logo">🖥️</div>
      <h2>Personal Code OS</h2>
      <p>브라우저 기반 완전 Self-Hosted 개발 환경</p>
      <div class="welcome-features">
        <div class="feature-item">⚡ FV-Lang REPL</div>
        <div class="feature-item">🐍 Python (Pyodide)</div>
        <div class="feature-item">💛 JavaScript</div>
        <div class="feature-item">🌿 Git VCS</div>
        <div class="feature-item">🤖 로컬 AI</div>
        <div class="feature-item">💾 OPFS 저장소</div>
      </div>
      <div class="welcome-shortcuts">
        <b>단축키</b><br>
        Ctrl+E: 에디터 | Ctrl+R: REPL | Ctrl+F: 파일관리자<br>
        Ctrl+G: Git | Ctrl+I: AI 어시스턴트
      </div>
      <div class="welcome-actions">
        <button onclick="document.querySelector('.os-window').querySelector('.btn-close')?.click(); window.os.launchApp('editor')">에디터 열기</button>
        <button onclick="window.os.launchApp('repl')">REPL 시작</button>
        <button onclick="window.os.launchApp('files')">파일 관리자</button>
      </div>
    `;

    this.wm.createWindow({
      title: '시작하기',
      icon: '🏠',
      width: 500,
      height: 450,
      x: 200,
      y: 50,
      resizable: false,
      content,
    });
  }

  _toggleStartMenu() {
    let menu = document.querySelector('.start-menu');
    if (menu) { menu.remove(); return; }

    menu = document.createElement('div');
    menu.className = 'start-menu';
    menu.innerHTML = `
      <div class="start-menu-title">🖥️ Personal Code OS</div>
      <div class="start-menu-item" data-app="editor">📝 코드 에디터</div>
      <div class="start-menu-item" data-app="repl">⚡ REPL</div>
      <div class="start-menu-item" data-app="files">📁 파일 관리자</div>
      <div class="start-menu-item" data-app="git">🌿 Git 뷰어</div>
      <div class="start-menu-item" data-app="ai">🤖 AI 어시스턴트</div>
      <hr>
      <div class="start-menu-item" data-app="settings">⚙️ 설정</div>
    `;

    menu.querySelectorAll('.start-menu-item[data-app]').forEach(item => {
      item.addEventListener('click', () => { menu.remove(); this.launchApp(item.dataset.app); });
    });

    document.body.appendChild(menu);
    setTimeout(() => document.addEventListener('click', () => menu.remove(), { once: true }), 50);
  }
}

// 부팅
window.addEventListener('DOMContentLoaded', async () => {
  const os = new PersonalCodeOS();
  window.os = os;
  await os.boot();
});

