/**
 * PersonalCodeOS - Runtime 단위 테스트
 * Node.js 환경에서 실행 가능 (브라우저 API 모킹)
 */

// ─── 브라우저 API 모킹 ──────────────────────────────────────────

global.crypto = {
  subtle: {
    digest: async (algorithm, data) => {
      // Node.js crypto 활용
      const nodeCrypto = await import('crypto');
      const hash = nodeCrypto.createHash('sha256').update(Buffer.from(data)).digest();
      return hash.buffer;
    }
  }
};

global.performance = { now: () => Date.now() };

// FVLangJSRuntime 직접 테스트 (모듈 import 없이)
class FVLangJSRuntime {
  constructor() {
    this.status = 'ready';
    this.version = 'FV-Lang 0.1.0 (JS interpreter)';
  }

  async run(code, opts = {}) {
    const logs = [];
    const errors = [];

    try {
      const tokens = this._tokenize(code);
      const ast = this._parse(tokens);
      const result = this._eval(ast, {}, logs);
      if (result !== undefined && result !== null) {
        logs.push(this._fmt(result));
      }
    } catch (e) {
      errors.push(`[FV-Lang Error] ${e.message}`);
      return { stdout: logs.join('\n'), stderr: errors.join('\n'), exitCode: 1 };
    }

    return {
      stdout: logs.join('\n'),
      stderr: errors.join('\n'),
      exitCode: 0,
    };
  }

  _tokenize(code) {
    const tokens = [];
    let i = 0;
    while (i < code.length) {
      if (/\s/.test(code[i])) { i++; continue; }
      if (code[i] === '#') { while (i < code.length && code[i] !== '\n') i++; continue; }
      if (code[i] === '"') {
        let j = i + 1;
        while (j < code.length && code[j] !== '"') { if (code[j] === '\\') j++; j++; }
        tokens.push({ type: 'string', value: code.slice(i + 1, j) });
        i = j + 1; continue;
      }
      if (/[0-9]/.test(code[i])) {
        let j = i;
        while (j < code.length && /[0-9.]/.test(code[j])) j++;
        tokens.push({ type: 'number', value: parseFloat(code.slice(i, j)) });
        i = j; continue;
      }
      const two = code.slice(i, i + 2);
      if (['==', '!=', '<=', '>=', '->', '=>', '::'].includes(two)) {
        tokens.push({ type: 'op', value: two }); i += 2; continue;
      }
      if ('+-*/%<>!(){}[]|&,;:.='.includes(code[i])) {
        tokens.push({ type: 'op', value: code[i] }); i++; continue;
      }
      if (/[a-zA-Z_]/.test(code[i])) {
        let j = i;
        while (j < code.length && /[a-zA-Z0-9_]/.test(code[j])) j++;
