        return { type: 'fn', name, params, body };
      }
      if (t.value === 'print') {
        consume(); expect('(');
        const args = [];
        while (peek()?.value !== ')') { args.push(parseExpr()); if (peek()?.value === ',') consume(); }
        expect(')'); return { type: 'print', args };
      }
      if (t.value === 'if') {
        consume(); const cond = parseExpr(); expect('{');
        const then = [];
        while (peek()?.value !== '}') then.push(parseStatement());
        expect('}');
        let els = null;
        if (peek()?.value === 'else') {
          consume(); expect('{'); els = [];
