  }

  _fmt(v) {
    if (v===null||v===undefined) return 'null';
    if (Array.isArray(v)) return '['+v.map(i=>this._fmt(i)).join(', ')+']';
    if (typeof v==='function') return `<fn ${v._name??'?'}>`;
    return String(v);
  }
}

// ─── 테스트 프레임워크 ──────────────────────────────────────────

let passed = 0, failed = 0, total = 0;

function test(name, fn) {
  total++;
  try {
    const result = fn();
    if (result instanceof Promise) {
      return result.then(() => { passed++; console.log(`  ✅ ${name}`); })
        .catch(e => { failed++; console.error(`  ❌ ${name}\n     ${e.message}`); });
    }
    passed++;
    console.log(`  ✅ ${name}`);
  } catch (e) {
    failed++;
    console.error(`  ❌ ${name}\n     ${e.message}`);
  }
}

function assert(cond, msg) {
  if (!cond) throw new Error(msg ?? 'Assertion failed');
}

function assertEquals(a, b) {
  if (a !== b) throw new Error(`Expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
}

// ─── FV-Lang 인터프리터 테스트 ──────────────────────────────────

async function runTests() {
  const rt = new FVLangJSRuntime();
  console.log('\n📋 FV-Lang Interpreter Tests\n');

  // 기본 리터럴
  const r1 = await rt.run('print(42)');
  test('숫자 출력', () => assertEquals(r1.stdout, '42'));

  const r2 = await rt.run('print("hello")');
  test('문자열 출력', () => assertEquals(r2.stdout, 'hello'));

  const r3 = await rt.run('print(true)');
  test('불리언 true', () => assertEquals(r3.stdout, 'true'));

  const r4 = await rt.run('print(false)');
  test('불리언 false', () => assertEquals(r4.stdout, 'false'));

  // 산술
  const r5 = await rt.run('print(1 + 2)');
  test('덧셈', () => assertEquals(r5.stdout, '3'));

  const r6 = await rt.run('print(10 - 3)');
  test('뺄셈', () => assertEquals(r6.stdout, '7'));

  const r7 = await rt.run('print(3 * 4)');
  test('곱셈', () => assertEquals(r7.stdout, '12'));

  const r8 = await rt.run('print(10 / 2)');
  test('나눗셈', () => assertEquals(r8.stdout, '5'));

  const r9 = await rt.run('print(10 % 3)');
  test('나머지', () => assertEquals(r9.stdout, '1'));

  // 비교
  const r10 = await rt.run('print(1 == 1)');
  test('동등', () => assertEquals(r10.stdout, 'true'));

  const r11 = await rt.run('print(1 != 2)');
  test('불동등', () => assertEquals(r11.stdout, 'true'));

  const r12 = await rt.run('print(5 > 3)');
  test('크다', () => assertEquals(r12.stdout, 'true'));

  const r13 = await rt.run('print(3 < 5)');
  test('작다', () => assertEquals(r13.stdout, 'true'));

  // 변수
  const r14 = await rt.run('let x = 42\nprint(x)');
  test('변수 선언', () => assertEquals(r14.stdout, '42'));

  const r15 = await rt.run('let name = "world"\nprint("hello " + name)');
  test('문자열 연결', () => assertEquals(r15.stdout, 'hello world'));

  // 함수
  const r16 = await rt.run('fn add(a, b) = a + b\nprint(add(3, 4))');
  test('함수 선언 & 호출', () => assertEquals(r16.stdout, '7'));

  const r17 = await rt.run('fn double(x) = x * 2\nprint(double(5))');
  test('단인자 함수', () => assertEquals(r17.stdout, '10'));

  const r18 = await rt.run('fn square(n) = n * n\nprint(square(9))');
  test('제곱 함수', () => assertEquals(r18.stdout, '81'));

  // 재귀
  const r19 = await rt.run(`
fn fib(n) = if n <= 1 { n } else { fib(n - 1) + fib(n - 2) }
print(fib(10))
  `);
  test('피보나치 재귀 (fib(10))', () => assertEquals(r19.stdout, '55'));

  const r20 = await rt.run(`
fn fact(n) = if n <= 1 { 1 } else { n * fact(n - 1) }
print(fact(5))
  `);
  test('팩토리얼 재귀 (fact(5))', () => assertEquals(r20.stdout, '120'));

  // 조건문
  const r21 = await rt.run(`
let x = 10
if x > 5 {
  print("big")
} else {
  print("small")
}
  `);
  test('if/else 분기 (참)', () => assertEquals(r21.stdout, 'big'));

  const r22 = await rt.run(`
let x = 3
if x > 5 {
  print("big")
} else {
  print("small")
}
  `);
  test('if/else 분기 (거짓)', () => assertEquals(r22.stdout, 'small'));

  // 배열
  const r23 = await rt.run('let arr = [1, 2, 3]\nprint(arr)');
  test('배열 리터럴', () => assertEquals(r23.stdout, '[1, 2, 3]'));

  // 다중 출력
  const r24 = await rt.run('print(1)\nprint(2)\nprint(3)');
  test('다중 print', () => assertEquals(r24.stdout, '1\n2\n3'));

  // 고차 함수 (함수를 값으로)
  const r25 = await rt.run(`
fn apply(f, x) = f(x)
fn double(n) = n * 2
print(apply(double, 7))
  `);
  test('고차 함수 (apply)', () => assertEquals(r25.stdout, '14'));

  // 에러 처리
  const r26 = await rt.run('print(undefined_var)');
  test('미정의 변수 오류', () => assert(r26.exitCode !== 0));

  const r27 = await rt.run('let x = 10 / 0\nprint(x)');
  test('0 나눗셈 (Infinity)', () => assert(r27.stdout === 'Infinity' || r27.exitCode !== 0));

  // 주석
  const r28 = await rt.run(`
# 이것은 주석입니다
let x = 42
# print("무시됨")
print(x)
  `);
  test('주석 무시', () => assertEquals(r28.stdout, '42'));

  // 복잡한 표현식
  const r29 = await rt.run('print((2 + 3) * 4)');
  test('괄호 우선순위', () => assertEquals(r29.stdout, '20'));

  const r30 = await rt.run('print(2 + 3 * 4)');
  test('연산자 우선순위', () => assertEquals(r30.stdout, '14'));

  // 문자열 + 숫자
  const r31 = await rt.run('print("값: " + 42)');
  test('문자열+숫자 연결', () => assert(r31.stdout.includes('42')));

  // 중첩 함수 호출
  const r32 = await rt.run(`
fn add(a, b) = a + b
fn mul(a, b) = a * b
print(add(mul(2, 3), mul(4, 5)))
  `);
  test('중첩 함수 호출', () => assertEquals(r32.stdout, '26'));

  // 논리 부정
  const r33 = await rt.run('print(!true)');
  test('논리 부정 (!true)', () => assertEquals(r33.stdout, 'false'));

  const r34 = await rt.run('print(!false)');
  test('논리 부정 (!false)', () => assertEquals(r34.stdout, 'true'));

  // null
  const r35 = await rt.run('print(null)');
  test('null 출력', () => assertEquals(r35.stdout, 'null'));

  // 큰 수
  const r36 = await rt.run('print(1000000 * 1000000)');
  test('큰 수 연산', () => assertEquals(r36.stdout, '1000000000000'));

  // 클로저 (함수 환경 캡처)
  const r37 = await rt.run(`
let base = 10
fn addBase(x) = x + base
print(addBase(5))
  `);
  test('클로저 (환경 캡처)', () => assertEquals(r37.stdout, '15'));

  // 연속 let
  const r38 = await rt.run(`
let a = 10
let b = 20
let c = a + b
print(c)
  `);
  test('연속 변수 선언', () => assertEquals(r38.stdout, '30'));

  // 함수 재할당
  const r39 = await rt.run(`
fn greet(name) = "Hello, " + name
print(greet("World"))
print(greet("FV-Lang"))
  `);
  test('함수 다중 호출', () => assertEquals(r39.stdout, 'Hello, World\nHello, FV-Lang'));

  // 음수
  const r40 = await rt.run('print(-5)');
  test('음수 리터럴', () => assertEquals(r40.stdout, '-5'));

  // 전체 결과
  await new Promise(r => setTimeout(r, 100));
  console.log('\n' + '─'.repeat(40));
  console.log(`총 ${total}개 테스트: ✅ ${passed}개 통과, ❌ ${failed}개 실패`);
  console.log('─'.repeat(40) + '\n');

  process.exit(failed > 0 ? 1 : 0);
}

runTests().catch(e => { console.error(e); process.exit(1); });

