// FVLangJSRuntime 직접 테스트 (모듈 import 없이)
class FVLangJSRuntime {
  constructor() {
    this.status = 'ready';
    this.version = 'FV-Lang 0.1.0 (JS interpreter)';
  }

  async run(code, opts = {}) {
    const logs = [];
