/**
 * PersonalCodeOS - Runtime 단위 테스트
 * Node.js 환경에서 실행 가능 (브라우저 API 모킹)
 */

// ─── 브라우저 API 모킹 ──────────────────────────────────────────

global.crypto = {
  subtle: {
    digest: async (algorithm, data) => {
      // Node.js crypto 활용
      const nodeCrypto = await import('crypto');
      const hash = nodeCrypto.createHash('sha256').update(Buffer.from(data)).digest();
      return hash.buffer;
    }
  }
};

global.performance = { now: () => Date.now() };

// FVLangJSRuntime 직접 테스트 (모듈 import 없이)
class FVLangJSRuntime {
  constructor() {
    this.status = 'ready';
    this.version = 'FV-Lang 0.1.0 (JS interpreter)';
  }

  async run(code, opts = {}) {
    const logs = [];
    const errors = [];

    try {
      const tokens = this._tokenize(code);
      const ast = this._parse(tokens);
      const result = this._eval(ast, {}, logs);
      if (result !== undefined && result !== null) {
        logs.push(this._fmt(result));
      }
    } catch (e) {
      errors.push(`[FV-Lang Error] ${e.message}`);
      return { stdout: logs.join('\n'), stderr: errors.join('\n'), exitCode: 1 };
    }

    return {
      stdout: logs.join('\n'),
      stderr: errors.join('\n'),
      exitCode: 0,
    };
  }

  _tokenize(code) {
    const tokens = [];
    let i = 0;
    while (i < code.length) {
      if (/\s/.test(code[i])) { i++; continue; }
      if (code[i] === '#') { while (i < code.length && code[i] !== '\n') i++; continue; }
      if (code[i] === '"') {
        let j = i + 1;
        while (j < code.length && code[j] !== '"') { if (code[j] === '\\') j++; j++; }
        tokens.push({ type: 'string', value: code.slice(i + 1, j) });
        i = j + 1; continue;
      }
      if (/[0-9]/.test(code[i])) {
        let j = i;
        while (j < code.length && /[0-9.]/.test(code[j])) j++;
        tokens.push({ type: 'number', value: parseFloat(code.slice(i, j)) });
        i = j; continue;
      }
      const two = code.slice(i, i + 2);
      if (['==', '!=', '<=', '>=', '->', '=>', '::'].includes(two)) {
        tokens.push({ type: 'op', value: two }); i += 2; continue;
      }
      if ('+-*/%<>!(){}[]|&,;:.='.includes(code[i])) {
        tokens.push({ type: 'op', value: code[i] }); i++; continue;
      }
      if (/[a-zA-Z_]/.test(code[i])) {
        let j = i;
        while (j < code.length && /[a-zA-Z0-9_]/.test(code[j])) j++;
        const word = code.slice(i, j);
        const keywords = new Set(['let', 'fn', 'if', 'else', 'match', 'true', 'false', 'print', 'return', 'type', 'import', 'do', 'end', 'for', 'in', 'while', 'null']);
        tokens.push({ type: keywords.has(word) ? 'keyword' : 'ident', value: word });
        i = j; continue;
      }
      i++;
    }
    return tokens;
  }

  _parse(tokens) {
    let pos = 0;
    const peek = () => tokens[pos];
    const consume = () => tokens[pos++];
    const expect = (v) => {
      const t = consume();
      if (t?.value !== v) throw new Error(`Expected '${v}', got '${t?.value}'`);
      return t;
    };

    function parseExpr() { return parseComparison(); }
    function parseComparison() {
      let left = parseAddSub();
      while (peek() && ['==', '!=', '<', '>', '<=', '>='].includes(peek().value)) {
        const op = consume().value; const right = parseAddSub();
        left = { type: 'binary', op, left, right };
      }
      return left;
    }
    function parseAddSub() {
      let left = parseMulDiv();
      while (peek() && ['+', '-'].includes(peek().value)) {
        const op = consume().value; const right = parseMulDiv();
        left = { type: 'binary', op, left, right };
      }
      return left;
    }
    function parseMulDiv() {
      let left = parseUnary();
      while (peek() && ['*', '/', '%'].includes(peek().value)) {
        const op = consume().value; const right = parseUnary();
        left = { type: 'binary', op, left, right };
      }
      return left;
    }
    function parseUnary() {
      if (peek()?.value === '-') { consume(); return { type: 'unary', op: '-', expr: parseUnary() }; }
      if (peek()?.value === '!') { consume(); return { type: 'unary', op: '!', expr: parseUnary() }; }
      return parseCall();
    }
    function parseCall() {
      let expr = parsePrimary();
      while (peek()?.value === '(') {
        consume();
        const args = [];
        while (peek() && peek().value !== ')') { args.push(parseExpr()); if (peek()?.value === ',') consume(); }
        expect(')');
        expr = { type: 'call', callee: expr, args };
      }
      return expr;
    }
    function parsePrimary() {
      const t = peek();
      if (!t) throw new Error('Unexpected end of input');
      if (t.type === 'number') { consume(); return { type: 'number', value: t.value }; }
      if (t.type === 'string') { consume(); return { type: 'string', value: t.value }; }
      if (t.value === 'true') { consume(); return { type: 'bool', value: true }; }
      if (t.value === 'false') { consume(); return { type: 'bool', value: false }; }
      if (t.value === 'null') { consume(); return { type: 'null' }; }
      if (t.value === '(') { consume(); const expr = parseExpr(); expect(')'); return expr; }
      if (t.value === '[') {
        consume(); const items = [];
        while (peek()?.value !== ']') { items.push(parseExpr()); if (peek()?.value === ',') consume(); }
        expect(']'); return { type: 'array', items };
      }
      if (t.type === 'ident') { consume(); return { type: 'ident', name: t.value }; }
      throw new Error(`Unexpected token: '${t.value}'`);
    }
    function parseStatement() {
      const t = peek();
      if (!t) return null;
      if (t.value === 'let') {
        consume(); const name = consume().value; expect('='); const value = parseExpr();
        return { type: 'let', name, value };
      }
      if (t.value === 'fn') {
        consume(); const name = consume().value; expect('(');
        const params = [];
        while (peek()?.value !== ')') { params.push(consume().value); if (peek()?.value === ',') consume(); }
        expect(')'); expect('='); const body = parseExpr();
        return { type: 'fn', name, params, body };
      }
      if (t.value === 'print') {
        consume(); expect('(');
        const args = [];
        while (peek()?.value !== ')') { args.push(parseExpr()); if (peek()?.value === ',') consume(); }
        expect(')'); return { type: 'print', args };
      }
      if (t.value === 'if') {
        consume(); const cond = parseExpr(); expect('{');
        const then = [];
        while (peek()?.value !== '}') then.push(parseStatement());
        expect('}');
        let els = null;
        if (peek()?.value === 'else') {
          consume(); expect('{'); els = [];
          while (peek()?.value !== '}') els.push(parseStatement());
          expect('}');
        }
        return { type: 'if', cond, then, else: els };
      }
      if (t.value === 'return') { consume(); return { type: 'return', value: parseExpr() }; }
      return { type: 'expr', expr: parseExpr() };
    }
    const stmts = [];
    while (pos < tokens.length) { const s = parseStatement(); if (s) stmts.push(s); }
    return { type: 'program', body: stmts };
  }

  _eval(node, env, logs) {
    switch (node.type) {
      case 'program': { let last; for (const s of node.body) last = this._eval(s, env, logs); return last; }
      case 'number': return node.value;
      case 'string': return node.value;
      case 'bool': return node.value;
      case 'null': return null;
      case 'ident': { if (!(node.name in env)) throw new Error(`Undefined: ${node.name}`); return env[node.name]; }
      case 'array': return node.items.map(i => this._eval(i, env, logs));
      case 'let': { const v = this._eval(node.value, env, logs); env[node.name] = v; return v; }
      case 'fn': { const fn = (...args) => { const e = {...env}; node.params.forEach((p,i) => e[p]=args[i]); return this._eval(node.body, e, logs); }; fn._name=node.name; fn._params=node.params; env[node.name]=fn; return fn; }
      case 'call': { const c = this._eval(node.callee, env, logs); if (typeof c!=='function') throw new Error('Not a function'); return c(...node.args.map(a=>this._eval(a,env,logs))); }
      case 'print': { logs.push(node.args.map(a=>this._fmt(this._eval(a,env,logs))).join(' ')); return null; }
      case 'binary': {
        const l=this._eval(node.left,env,logs), r=this._eval(node.right,env,logs);
        switch(node.op) {
          case '+': return l+r; case '-': return l-r; case '*': return l*r; case '/': return l/r; case '%': return l%r;
          case '==': return l===r; case '!=': return l!==r; case '<': return l<r; case '>': return l>r; case '<=': return l<=r; case '>=': return l>=r;
        } break;
      }
      case 'unary': if(node.op==='-') return -this._eval(node.expr,env,logs); if(node.op==='!') return !this._eval(node.expr,env,logs); break;
      case 'if': { const c=this._eval(node.cond,env,logs); const b=c?node.then:node.else; if(!b) return null; let r; for(const s of b) r=this._eval(s,env,logs); return r??null; }
      case 'return': throw { __return: this._eval(node.value, env, logs) };
      case 'expr': return this._eval(node.expr, env, logs);
    }
    return null;
  }

  _fmt(v) {
    if (v===null||v===undefined) return 'null';
    if (Array.isArray(v)) return '['+v.map(i=>this._fmt(i)).join(', ')+']';
    if (typeof v==='function') return `<fn ${v._name??'?'}>`;
    return String(v);
  }
}

