/**
 * FreeWire - Phase 4: 노드 에디터 UI
 * 순수 Canvas + SVG 기반 (외부 의존성 없음)
 *
 * 기능:
 * - 노드 드래그/이동
 * - 포트 연결 (호환 타입 검증)
 * - 실시간 SVG 와이어 렌더링 (베지어 곡선)
 * - 노드 팔레트 (component/data/logic)
 * - FreeExecutor API 연동 (컴파일 + 실행)
 * - 그래프 JSON 직렬화/역직렬화
 */

'use strict';

// ─── 포트 타입 컬러 ──────────────────────────────────────────────
const PORT_COLORS = {
  component: '#58a6ff',
  data:      '#3fb950',
  logic:     '#d29922',
  event:     '#bc8cff',
  any:       '#8b949e',
};

const PORT_COMPAT = {
  component: ['component', 'any'],
  data:      ['data', 'any'],
  logic:     ['logic', 'any'],
  event:     ['event', 'any'],
  any:       ['component', 'data', 'logic', 'event', 'any'],
};

// ─── 노드 팔레트 정의 ────────────────────────────────────────────
const NODE_PALETTE = [
  {
    label: '컴포넌트',
    nodes: [
      { label: '버튼', type: 'component', subtype: 'button',
        inputs: [{ name: 'props', portType: 'data' }, { name: 'onClick', portType: 'logic' }],
        outputs: [{ name: 'element', portType: 'component' }],
        props: { label: '클릭', variant: 'primary' } },
      { label: '텍스트', type: 'component', subtype: 'text',
        inputs: [{ name: 'content', portType: 'data' }],
        outputs: [{ name: 'element', portType: 'component' }],
        props: { content: '텍스트', tag: 'p' } },
      { label: '입력', type: 'component', subtype: 'input',
        inputs: [{ name: 'value', portType: 'data' }, { name: 'onChange', portType: 'logic' }],
        outputs: [{ name: 'element', portType: 'component' }, { name: 'value', portType: 'data' }],
        props: { placeholder: '입력하세요', type: 'text' } },
      { label: '카드', type: 'component', subtype: 'card',
        inputs: [{ name: 'title', portType: 'data' }, { name: 'children', portType: 'component' }],
        outputs: [{ name: 'element', portType: 'component' }],
        props: { title: '카드 제목' } },
      { label: '컨테이너', type: 'component', subtype: 'container',
        inputs: [{ name: 'children', portType: 'component' }],
        outputs: [{ name: 'element', portType: 'component' }],
        props: { direction: 'column', gap: '8px' } },
    ],
  },
  {
    label: '데이터',
    nodes: [
      { label: '상수', type: 'data', subtype: 'const',
        inputs: [],
        outputs: [{ name: 'value', portType: 'data' }],
        props: { value: '42', valueType: 'number' } },
      { label: '상태', type: 'data', subtype: 'state',
        inputs: [{ name: 'set', portType: 'data' }],
        outputs: [{ name: 'value', portType: 'data' }],
        props: { name: 'count', initial: '0' } },
      { label: '배열', type: 'data', subtype: 'array',
        inputs: [],
        outputs: [{ name: 'items', portType: 'data' }],
        props: { items: '[]' } },
      { label: 'Props', type: 'data', subtype: 'props',
        inputs: [],
        outputs: [{ name: 'props', portType: 'data' }],
        props: { fields: '{}' } },
    ],
  },
  {
    label: '로직',
    nodes: [
      { label: '이벤트핸들러', type: 'logic', subtype: 'handler',
        inputs: [{ name: 'action', portType: 'logic' }],
        outputs: [{ name: 'handler', portType: 'logic' }],
        props: { name: 'handleClick' } },
      { label: 'setState', type: 'logic', subtype: 'setState',
        inputs: [{ name: 'trigger', portType: 'event' }, { name: 'value', portType: 'data' }],
        outputs: [{ name: 'done', portType: 'event' }],
        props: { target: '' } },
      { label: 'if/else', type: 'logic', subtype: 'condition',
        inputs: [{ name: 'condition', portType: 'data' }],
        outputs: [{ name: 'true', portType: 'logic' }, { name: 'false', portType: 'logic' }],
        props: { operator: '==', value: 'true' } },
    ],
  },
];

// ─── NodeEditorUI 클래스 ─────────────────────────────────────────

class NodeEditorUI {
  constructor(container) {
    this.container = container;
    this.nodes = new Map();        // id → NodeView
    this.wires = new Map();        // id → WireView
    this.nodeIdCounter = 1;
    this.wireIdCounter = 1;

    this.selectedNode = null;
    this.dragState = null;         // 노드 드래그
    this.wireState = null;         // 와이어 드래그 중

    this.viewport = { x: 0, y: 0, scale: 1 };
    this.panState = null;

    this._build();
    this._bindEvents();
  }

  // ─── UI 빌드 ──────────────────────────────────────────────────

  _build() {
    this.container.innerHTML = '';
    this.container.style.cssText = 'display:flex;flex-direction:row;height:100%;overflow:hidden;background:#0d1117;';

    // 팔레트
    this.paletteEl = document.createElement('div');
    this.paletteEl.className = 'fw-palette';
    this.paletteEl.style.cssText = `
      width:180px;flex-shrink:0;background:#161b22;border-right:1px solid #30363d;
      overflow-y:auto;display:flex;flex-direction:column;
    `;
    this._buildPalette();

    // 캔버스 영역
    this.canvasWrap = document.createElement('div');
    this.canvasWrap.style.cssText = 'flex:1;position:relative;overflow:hidden;';

    // SVG 와이어 레이어
    this.svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    this.svg.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:1;';
    this.svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');

    // 그리드 패턴
    this.svg.innerHTML = `
      <defs>
        <pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse">
          <path d="M 20 0 L 0 0 0 20" fill="none" stroke="rgba(255,255,255,0.04)" stroke-width="1"/>
        </pattern>
        <marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto">
          <path d="M 0 0 L 0 6 L 9 3 z" fill="#58a6ff" opacity="0.8"/>
        </marker>
      </defs>
      <rect width="100%" height="100%" fill="url(#grid)"/>
      <g class="wires-layer"></g>
      <path class="wire-preview" d="" fill="none" stroke="#58a6ff" stroke-width="2" stroke-dasharray="6,3" opacity="0.7"/>
    `;

    this.wiresLayer = this.svg.querySelector('.wires-layer');
    this.wirePreview = this.svg.querySelector('.wire-preview');

    // 노드 레이어 (div, SVG 위)
    this.nodesLayer = document.createElement('div');
    this.nodesLayer.style.cssText = 'position:absolute;inset:0;z-index:2;';

    this.canvasWrap.appendChild(this.svg);
    this.canvasWrap.appendChild(this.nodesLayer);

    // 툴바
    this.toolbar = document.createElement('div');
    this.toolbar.style.cssText = `
      position:absolute;top:8px;right:8px;z-index:10;
      display:flex;gap:6px;
    `;
    this.toolbar.innerHTML = `
      <button class="fw-btn" data-action="compile" title="FreeLang으로 컴파일">⚡ 컴파일</button>
      <button class="fw-btn" data-action="run" title="실행">▶ 실행</button>
      <button class="fw-btn" data-action="clear" title="전체 삭제">🗑️ 초기화</button>
      <button class="fw-btn" data-action="export" title="JSON 내보내기">📤 내보내기</button>
      <button class="fw-btn" data-action="import" title="JSON 가져오기">📥 가져오기</button>
      <button class="fw-btn" data-action="fit" title="화면 맞추기">⊕ 맞추기</button>
    `;
    this.canvasWrap.appendChild(this.toolbar);

    // 출력 패널
    this.outputPanel = document.createElement('div');
    this.outputPanel.style.cssText = `
      position:absolute;bottom:0;left:0;right:0;height:160px;
      background:rgba(13,17,23,.95);border-top:1px solid #30363d;
      font-family:monospace;font-size:12px;z-index:10;display:flex;flex-direction:column;
    `;
    this.outputPanel.innerHTML = `
      <div style="display:flex;align-items:center;gap:8px;padding:4px 10px;background:#21262d;border-bottom:1px solid #30363d;flex-shrink:0;">
        <span style="color:#8b949e;font-size:11px;">출력</span>
        <span class="fw-output-lang" style="color:#58a6ff;font-size:11px;"></span>
        <button class="fw-btn fw-btn-sm" data-action="clear-output" style="margin-left:auto;">지우기</button>
      </div>
      <pre class="fw-output-content" style="flex:1;overflow:auto;padding:8px 12px;margin:0;color:#e6edf3;white-space:pre-wrap;word-break:break-all;"></pre>
    `;
    this.canvasWrap.appendChild(this.outputPanel);

    this.container.appendChild(this.paletteEl);
    this.container.appendChild(this.canvasWrap);

    // 출력 높이 반영
    this.nodesLayer.style.bottom = '160px';
    this.svg.style.bottom = '160px';
    this.svg.style.height = 'calc(100% - 160px)';
  }

  _buildPalette() {
    this.paletteEl.innerHTML = `<div style="padding:8px 10px;font-size:11px;font-weight:700;color:#58a6ff;border-bottom:1px solid #30363d;">📦 노드 팔레트</div>`;

    for (const group of NODE_PALETTE) {
      const header = document.createElement('div');
      header.style.cssText = 'padding:6px 10px;font-size:10px;font-weight:700;color:#8b949e;text-transform:uppercase;letter-spacing:0.8px;margin-top:4px;';
      header.textContent = group.label;
      this.paletteEl.appendChild(header);

      for (const def of group.nodes) {
        const item = document.createElement('div');
        item.className = 'fw-palette-item';
        item.style.cssText = `
          padding:7px 12px;cursor:grab;font-size:12px;color:#e6edf3;
          border-radius:4px;margin:1px 4px;transition:background .1s;
          display:flex;align-items:center;gap:6px;
        `;
        const dot = document.createElement('span');
        dot.style.cssText = `width:8px;height:8px;border-radius:50%;background:${PORT_COLORS[def.type] ?? '#8b949e'};flex-shrink:0;`;
        item.appendChild(dot);
        item.appendChild(document.createTextNode(def.label));

        item.addEventListener('mouseenter', () => item.style.background = 'rgba(255,255,255,.07)');
        item.addEventListener('mouseleave', () => item.style.background = '');

        // 더블클릭: 캔버스 중앙에 추가
        item.addEventListener('dblclick', () => {
          const rect = this.canvasWrap.getBoundingClientRect();
          const x = (rect.width / 2 - this.viewport.x) / this.viewport.scale - 80;
          const y = (rect.height / 2 - this.viewport.y) / this.viewport.scale - 40;
          this._addNode(def, x, y);
        });

        // 드래그로 추가
        item.setAttribute('draggable', 'true');
        item.addEventListener('dragstart', (e) => {
          e.dataTransfer.setData('fw-node-def', JSON.stringify(def));
        });

        this.paletteEl.appendChild(item);
      }
    }
  }

  // ─── 이벤트 바인딩 ────────────────────────────────────────────

  _bindEvents() {
    // 드롭 영역
    this.canvasWrap.addEventListener('dragover', (e) => e.preventDefault());
    this.canvasWrap.addEventListener('drop', (e) => {
      e.preventDefault();
      const raw = e.dataTransfer.getData('fw-node-def');
      if (!raw) return;
      const def = JSON.parse(raw);
      const rect = this.canvasWrap.getBoundingClientRect();
      const x = (e.clientX - rect.left - this.viewport.x) / this.viewport.scale - 80;
      const y = (e.clientY - rect.top - this.viewport.y) / this.viewport.scale - 40;
      this._addNode(def, x, y);
    });

    // 툴바 버튼
    this.toolbar.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-action]');
      if (!btn) return;
      this._handleToolbar(btn.dataset.action);
    });

    this.outputPanel.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-action]');
      if (btn?.dataset.action === 'clear-output') {
        this.outputPanel.querySelector('.fw-output-content').textContent = '';
        this.outputPanel.querySelector('.fw-output-lang').textContent = '';
      }
    });

    // 캔버스 패닝
    this.canvasWrap.addEventListener('mousedown', (e) => {
      if (e.target === this.canvasWrap || e.target === this.svg || e.target.tagName === 'rect') {
        this.panState = { startX: e.clientX - this.viewport.x, startY: e.clientY - this.viewport.y };
        this.canvasWrap.style.cursor = 'grabbing';
      }
    });

    document.addEventListener('mousemove', (e) => {
      if (this.panState) {
        this.viewport.x = e.clientX - this.panState.startX;
        this.viewport.y = e.clientY - this.panState.startY;
        this._applyViewport();
      }
      if (this.dragState) {
        this._onNodeDrag(e);
      }
      if (this.wireState) {
        this._onWireDrag(e);
      }
    });

    document.addEventListener('mouseup', (e) => {
      if (this.panState) {
        this.panState = null;
        this.canvasWrap.style.cursor = '';
      }
      if (this.dragState) {
        this.dragState = null;
      }
      if (this.wireState) {
        this._onWireDrop(e);
      }
    });

    // 줌
    this.canvasWrap.addEventListener('wheel', (e) => {
      e.preventDefault();
      const delta = e.deltaY > 0 ? 0.9 : 1.1;
      const rect = this.canvasWrap.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      this.viewport.x = mx - (mx - this.viewport.x) * delta;
      this.viewport.y = my - (my - this.viewport.y) * delta;
      this.viewport.scale = Math.max(0.2, Math.min(3, this.viewport.scale * delta));
      this._applyViewport();
    }, { passive: false });

    // 선택 해제
    this.nodesLayer.addEventListener('mousedown', (e) => {
      if (e.target === this.nodesLayer) this._selectNode(null);
    });
  }

  // ─── 뷰포트 ───────────────────────────────────────────────────

  _applyViewport() {
    this.nodesLayer.style.transform = `translate(${this.viewport.x}px,${this.viewport.y}px) scale(${this.viewport.scale})`;
    this.nodesLayer.style.transformOrigin = '0 0';

    // SVG 그리드 업데이트
    const grid = this.svg.querySelector('pattern');
    if (grid) {
      const s = this.viewport.scale;
      grid.setAttribute('width', 20 * s);
      grid.setAttribute('height', 20 * s);
      grid.setAttribute('patternTransform', `translate(${this.viewport.x % (20 * s)},${this.viewport.y % (20 * s)})`);
    }

    this._redrawAllWires();
  }

  _fitView() {
    if (this.nodes.size === 0) return;
    let minX=Infinity, minY=Infinity, maxX=-Infinity, maxY=-Infinity;
    for (const nv of this.nodes.values()) {
      minX = Math.min(minX, nv.x);
      minY = Math.min(minY, nv.y);
      maxX = Math.max(maxX, nv.x + nv.width);
      maxY = Math.max(maxY, nv.y + nv.height);
    }

    const rect = this.canvasWrap.getBoundingClientRect();
    const pw = rect.width - 40, ph = rect.height - 200;
    const sw = pw / (maxX - minX || 1);
    const sh = ph / (maxY - minY || 1);
    this.viewport.scale = Math.max(0.2, Math.min(1.5, Math.min(sw, sh)));
    this.viewport.x = (rect.width - (maxX - minX) * this.viewport.scale) / 2 - minX * this.viewport.scale;
    this.viewport.y = (ph - (maxY - minY) * this.viewport.scale) / 2 - minY * this.viewport.scale + 20;
    this._applyViewport();
  }

  // ─── 노드 생성 ────────────────────────────────────────────────

  _addNode(def, x, y) {
    const id = `node-${this.nodeIdCounter++}`;
    const nv = new NodeView(id, def, x, y, this);
    this.nodes.set(id, nv);
    this.nodesLayer.appendChild(nv.el);
    this._selectNode(id);
    return nv;
  }

  _removeNode(id) {
    // 연결된 와이어 제거
    for (const [wid, wire] of this.wires) {
      if (wire.fromNode === id || wire.toNode === id) {
        this._removeWire(wid);
      }
    }
    const nv = this.nodes.get(id);
    if (nv) { nv.el.remove(); this.nodes.delete(id); }
    if (this.selectedNode === id) this._selectNode(null);
  }

  _selectNode(id) {
    this.selectedNode = id;
    for (const [nid, nv] of this.nodes) {
      nv.el.classList.toggle('selected', nid === id);
    }
  }

  // ─── 드래그 ───────────────────────────────────────────────────

  startNodeDrag(nodeId, e) {
    const nv = this.nodes.get(nodeId);
    this.dragState = {
      nodeId,
      startMouseX: e.clientX,
      startMouseY: e.clientY,
      startNodeX: nv.x,
      startNodeY: nv.y,
    };
    this._selectNode(nodeId);
    e.preventDefault();
  }

  _onNodeDrag(e) {
    if (!this.dragState) return;
    const { nodeId, startMouseX, startMouseY, startNodeX, startNodeY } = this.dragState;
    const nv = this.nodes.get(nodeId);
    if (!nv) return;
    const dx = (e.clientX - startMouseX) / this.viewport.scale;
    const dy = (e.clientY - startMouseY) / this.viewport.scale;
    nv.x = startNodeX + dx;
    nv.y = startNodeY + dy;
    nv.el.style.left = `${nv.x}px`;
    nv.el.style.top = `${nv.y}px`;
    this._redrawWiresForNode(nodeId);
  }

  // ─── 와이어 ───────────────────────────────────────────────────

  startWireDrag(nodeId, portIdx, isOutput, portEl) {
    const pos = this._getPortPos(nodeId, portIdx, isOutput);
    this.wireState = { fromNode: nodeId, fromPort: portIdx, fromOutput: isOutput, startPos: pos };
  }

  _onWireDrag(e) {
    if (!this.wireState) return;
    const { startPos } = this.wireState;
    const rect = this.canvasWrap.getBoundingClientRect();
    const mx = (e.clientX - rect.left - this.viewport.x) / this.viewport.scale;
    const my = (e.clientY - rect.top - this.viewport.y) / this.viewport.scale;
    this.wirePreview.setAttribute('d', this._bezier(startPos.x, startPos.y, mx, my));
  }

  _onWireDrop(e) {
    this.wirePreview.setAttribute('d', '');
    if (!this.wireState) return;
    const ws = this.wireState;
    this.wireState = null;

    // 포트 히트 테스트
    const rect = this.canvasWrap.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    for (const [nid, nv] of this.nodes) {
      if (nid === ws.fromNode) continue;
      const portEls = nv.el.querySelectorAll('.fw-port');
      for (const portEl of portEls) {
        const pr = portEl.getBoundingClientRect();
        if (mx >= pr.left - 8 && mx <= pr.right + 8 && my >= pr.top - 8 && my <= pr.bottom + 8) {
          const portIdx = parseInt(portEl.dataset.portIdx);
          const isOutput = portEl.dataset.isOutput === '1';

          // 방향: 출력→입력 연결만 허용
          let fromNode, fromPort, toNode, toPort;
          if (ws.fromOutput && !isOutput) {
            fromNode = ws.fromNode; fromPort = ws.fromPort;
            toNode = nid; toPort = portIdx;
          } else if (!ws.fromOutput && isOutput) {
            fromNode = nid; fromPort = portIdx;
            toNode = ws.fromNode; toPort = ws.fromPort;
          } else {
            this._showMsg('같은 방향의 포트끼리는 연결할 수 없습니다', 'warn');
            return;
          }

          // 타입 호환성 체크
          const fromNv = this.nodes.get(fromNode);
          const toNv = this.nodes.get(toNode);
          const outType = fromNv.def.outputs[fromPort]?.portType ?? 'any';
          const inType = toNv.def.inputs[toPort]?.portType ?? 'any';

          if (!(PORT_COMPAT[outType] ?? []).includes(inType)) {
            this._showMsg(`타입 불일치: ${outType} → ${inType}`, 'error');
            return;
          }

          this._addWire(fromNode, fromPort, toNode, toPort, outType);
          return;
        }
      }
    }
  }

  _addWire(fromNode, fromPort, toNode, toPort, portType) {
    // 중복 체크
    for (const w of this.wires.values()) {
      if (w.fromNode === fromNode && w.fromPort === fromPort && w.toNode === toNode && w.toPort === toPort) return;
    }

    const id = `wire-${this.wireIdCounter++}`;
    const wire = { id, fromNode, fromPort, toNode, toPort, portType };
    this.wires.set(id, wire);
    this._drawWire(wire);
  }

  _removeWire(id) {
    const el = this.wiresLayer.querySelector(`[data-wire="${id}"]`);
    if (el) el.remove();
    this.wires.delete(id);
  }

  _drawWire(wire) {
    const from = this._getPortPos(wire.fromNode, wire.fromPort, true);
    const to = this._getPortPos(wire.toNode, wire.toPort, false);
    const color = PORT_COLORS[wire.portType] ?? PORT_COLORS.any;

    // 기존 제거
    this.wiresLayer.querySelector(`[data-wire="${wire.id}"]`)?.remove();

    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('data-wire', wire.id);
    path.setAttribute('d', this._bezier(from.x, from.y, to.x, to.y));
    path.setAttribute('fill', 'none');
    path.setAttribute('stroke', color);
    path.setAttribute('stroke-width', '2.5');
    path.setAttribute('opacity', '0.85');
    path.style.cssText = 'cursor:pointer;';

    path.addEventListener('click', () => {
      if (confirm('이 연결을 삭제하시겠습니까?')) this._removeWire(wire.id);
    });

    this.wiresLayer.appendChild(path);
  }

  _redrawWiresForNode(nodeId) {
    for (const wire of this.wires.values()) {
      if (wire.fromNode === nodeId || wire.toNode === nodeId) {
        this._drawWire(wire);
      }
    }
  }

  _redrawAllWires() {
    for (const wire of this.wires.values()) this._drawWire(wire);
  }

  _getPortPos(nodeId, portIdx, isOutput) {
    const nv = this.nodes.get(nodeId);
    if (!nv) return { x: 0, y: 0 };

    const portEls = [...nv.el.querySelectorAll('.fw-port')];
    const target = portEls.find(p => parseInt(p.dataset.portIdx) === portIdx && p.dataset.isOutput === (isOutput ? '1' : '0'));

    if (!target) {
      return { x: nv.x + (isOutput ? nv.width : 0), y: nv.y + 40 };
    }

    const canvasRect = this.canvasWrap.getBoundingClientRect();
    const pr = target.getBoundingClientRect();
    return {
      x: (pr.left + pr.width / 2 - canvasRect.left - this.viewport.x) / this.viewport.scale,
      y: (pr.top + pr.height / 2 - canvasRect.top - this.viewport.y) / this.viewport.scale,
    };
  }

  _bezier(x1, y1, x2, y2) {
    const dx = Math.abs(x2 - x1) * 0.6 + 40;
    return `M ${x1} ${y1} C ${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`;
  }

  // ─── 툴바 액션 ────────────────────────────────────────────────

  _handleToolbar(action) {
    switch (action) {
      case 'compile': return this._compile();
      case 'run':     return this._run();
      case 'clear':   return this._clearAll();
      case 'export':  return this._exportJSON();
      case 'import':  return this._importJSON();
      case 'fit':     return this._fitView();
    }
  }

  async _compile() {
    const graph = this._toGraphJSON();
    this._showOutput('컴파일 중...', 'FreeLang');

    try {
      const res = await fetch('http://localhost:4000/api/compile', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ graph }),
      });
      const data = await res.json();

      if (data.errors?.length > 0) {
        this._showOutput(`❌ 컴파일 오류:\n${data.errors.join('\n')}`, 'Error');
      } else {
        this._lastCompiledCode = data.code;
        this._showOutput(data.code, 'FreeLang');
        if (data.warnings?.length > 0) {
          this._showOutput(`⚠️ 경고:\n${data.warnings.join('\n')}\n\n` + data.code, 'FreeLang');
        }
      }
    } catch (e) {
      // API 서버 없으면 로컬 컴파일러 사용
      this._showOutput(`API 서버 연결 실패 (localhost:4000)\n로컬 컴파일 실행...\n\n${this._localCompile(graph)}`, 'FreeLang (로컬)');
    }
  }

  async _run() {
    if (!this._lastCompiledCode) {
      await this._compile();
    }
    if (!this._lastCompiledCode) return;

    try {
      const res = await fetch('http://localhost:4000/api/execute', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ graph: this._toGraphJSON() }),
      });
      const data = await res.json();
      const out = [
        data.output ? `출력:\n${data.output}` : '',
        data.html ? `HTML:\n${data.html.slice(0, 500)}...` : '',
        data.errors?.length ? `오류:\n${data.errors.join('\n')}` : '',
      ].filter(Boolean).join('\n\n');
      this._showOutput(out || '(출력 없음)', '실행 결과');
    } catch {
      this._showOutput('API 서버 없음. FreeWire 서버를 시작하세요:\nnode src/api/server.js', 'Error');
    }
  }

  _localCompile(graph) {
    // 간단한 로컬 컴파일 (노드 목록만)
    const lines = [];
    lines.push(`component MyApp {`);

    const compNodes = Object.values(graph.nodes ?? {}).filter(n => n.type === 'component');
    if (compNodes.length === 0) lines.push('  // 컴포넌트 노드를 추가하세요');
    else {
      lines.push('  markup {');
      for (const n of compNodes) {
        lines.push(`    ${n.subtype} { ${JSON.stringify(n.props ?? {})} }`);
      }
      lines.push('  }');
    }

    lines.push('}');
    return lines.join('\n');
  }

  _clearAll() {
    if (this.nodes.size === 0) return;
    if (!confirm('모든 노드와 연결을 삭제하시겠습니까?')) return;
    for (const id of [...this.nodes.keys()]) this._removeNode(id);
    this.wires.clear();
    this.wiresLayer.innerHTML = '';
    this._lastCompiledCode = null;
  }

  _exportJSON() {
    const json = JSON.stringify(this._toGraphJSON(), null, 2);
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'freewire-graph.json'; a.click();
    URL.revokeObjectURL(url);
  }

  _importJSON() {
    const input = document.createElement('input');
    input.type = 'file'; input.accept = '.json';
    input.onchange = async () => {
      const text = await input.files[0].text();
      try {
        this._fromGraphJSON(JSON.parse(text));
      } catch (e) {
        alert('JSON 파싱 오류: ' + e.message);
      }
    };
    input.click();
  }

  // ─── 그래프 직렬화 ────────────────────────────────────────────

  _toGraphJSON() {
    const nodes = {};
    for (const [id, nv] of this.nodes) {
      nodes[id] = {
        id,
        type: nv.def.type,
        subtype: nv.def.subtype,
        label: nv.def.label,
        inputs: nv.def.inputs,
        outputs: nv.def.outputs,
        props: { ...nv.def.props },
        position: { x: nv.x, y: nv.y },
      };
    }

    const edges = [];
    for (const w of this.wires.values()) {
      edges.push({
        id: w.id,
        from: w.fromNode,
        fromPort: w.fromPort,
        to: w.toNode,
        toPort: w.toPort,
      });
    }

    return { id: 'freewire-graph', nodes, edges };
  }

  _fromGraphJSON(json) {
    this._clearAll();

    for (const [id, nodeData] of Object.entries(json.nodes ?? {})) {
      const def = {
        label: nodeData.label ?? nodeData.subtype,
        type: nodeData.type,
        subtype: nodeData.subtype,
        inputs: nodeData.inputs ?? [],
        outputs: nodeData.outputs ?? [],
        props: nodeData.props ?? {},
      };
      const nv = new NodeView(id, def, nodeData.position?.x ?? 100, nodeData.position?.y ?? 100, this);
      this.nodes.set(id, nv);
      this.nodesLayer.appendChild(nv.el);
    }

    for (const edge of json.edges ?? []) {
      const fromNv = this.nodes.get(edge.from);
      const outType = fromNv?.def.outputs[edge.fromPort]?.portType ?? 'any';
      this._addWire(edge.from, edge.fromPort, edge.to, edge.toPort, outType);
    }
  }

  // ─── 출력 ────────────────────────────────────────────────────

  _showOutput(text, lang = '') {
    this.outputPanel.querySelector('.fw-output-content').textContent = text;
    this.outputPanel.querySelector('.fw-output-lang').textContent = lang ? `[${lang}]` : '';
  }

  _showMsg(msg, type = 'info') {
    const colors = { info: '#58a6ff', warn: '#d29922', error: '#f85149' };
    const div = document.createElement('div');
    div.style.cssText = `position:fixed;bottom:180px;right:20px;padding:8px 14px;border-radius:6px;background:#21262d;border:1px solid ${colors[type]};color:${colors[type]};font-size:12px;z-index:9999;`;
    div.textContent = msg;
    document.body.appendChild(div);
    setTimeout(() => div.remove(), 3000);
  }

  destroy() {
    this.nodes.clear();
    this.wires.clear();
  }
}

// ─── NodeView 클래스 ─────────────────────────────────────────────

class NodeView {
  constructor(id, def, x, y, editor) {
    this.id = id;
    this.def = { ...def, props: { ...(def.props ?? {}) } };
    this.x = x;
    this.y = y;
    this.editor = editor;
    this.width = 180;
    this.height = 0;

    this.el = document.createElement('div');
    this.el.className = 'fw-node';
    this.el.style.cssText = `
      position:absolute;left:${x}px;top:${y}px;width:${this.width}px;
      background:#161b22;border:1px solid #30363d;border-radius:8px;
      box-shadow:0 4px 16px rgba(0,0,0,.5);user-select:none;
    `;
    this.el.dataset.nodeId = id;

    this._render();
    requestAnimationFrame(() => {
      this.height = this.el.offsetHeight;
    });
  }

  _render() {
    const typeColor = PORT_COLORS[this.def.type] ?? '#8b949e';
    const maxPorts = Math.max(this.def.inputs.length, this.def.outputs.length);

    const inputRows = this.def.inputs.map((p, i) => `
      <div style="display:flex;align-items:center;gap:6px;padding:3px 8px;">
        <div class="fw-port" data-port-idx="${i}" data-is-output="0" data-node="${this.id}"
          style="width:10px;height:10px;border-radius:50%;background:${PORT_COLORS[p.portType]??'#8b949e'};
          border:2px solid #0d1117;cursor:crosshair;flex-shrink:0;">
        </div>
        <span style="font-size:11px;color:#8b949e;">${p.name}</span>
      </div>
    `).join('');

    const outputRows = this.def.outputs.map((p, i) => `
      <div style="display:flex;align-items:center;justify-content:flex-end;gap:6px;padding:3px 8px;">
        <span style="font-size:11px;color:#8b949e;">${p.name}</span>
        <div class="fw-port" data-port-idx="${i}" data-is-output="1" data-node="${this.id}"
          style="width:10px;height:10px;border-radius:50%;background:${PORT_COLORS[p.portType]??'#8b949e'};
          border:2px solid #0d1117;cursor:crosshair;flex-shrink:0;">
        </div>
      </div>
    `).join('');

    // Props 편집 필드
    const propsRows = Object.entries(this.def.props).map(([k, v]) => `
      <div style="display:flex;align-items:center;gap:4px;padding:2px 8px;">
        <span style="font-size:10px;color:#8b949e;min-width:50px;">${k}</span>
        <input class="fw-prop-input" data-key="${k}" value="${v ?? ''}"
          style="flex:1;background:#0d1117;border:1px solid #30363d;color:#e6edf3;padding:2px 6px;border-radius:3px;font-size:11px;min-width:0;">
      </div>
    `).join('');

    this.el.innerHTML = `
      <div class="fw-node-titlebar"
        style="padding:8px 10px;border-bottom:1px solid #30363d;background:${typeColor}18;
        border-radius:8px 8px 0 0;cursor:move;display:flex;align-items:center;justify-content:space-between;">
        <span style="font-size:12px;font-weight:700;color:${typeColor};">${this.def.label}</span>
        <div style="display:flex;gap:4px;">
          <span style="font-size:9px;color:#8b949e;padding:1px 5px;background:#21262d;border-radius:3px;">${this.def.type}</span>
          <button class="fw-node-del" style="background:none;border:none;color:#8b949e;cursor:pointer;padding:0 2px;font-size:13px;line-height:1;">✕</button>
        </div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:2px;padding:4px 0;">
        <div class="fw-inputs">${inputRows}</div>
        <div class="fw-outputs">${outputRows}</div>
      </div>
      ${propsRows ? `<div style="border-top:1px solid #30363d;padding:4px 0;">${propsRows}</div>` : ''}
    `;

    this._bindNodeEvents();
  }

  _bindNodeEvents() {
    // 드래그
    const titlebar = this.el.querySelector('.fw-node-titlebar');
    titlebar.addEventListener('mousedown', (e) => {
      if (e.target.classList.contains('fw-node-del')) return;
      this.editor.startNodeDrag(this.id, e);
    });

    // 삭제
    this.el.querySelector('.fw-node-del').addEventListener('click', () => {
      this.editor._removeNode(this.id);
    });

    // 포트 와이어 시작
    this.el.querySelectorAll('.fw-port').forEach(port => {
      port.addEventListener('mousedown', (e) => {
        e.stopPropagation();
        const idx = parseInt(port.dataset.portIdx);
        const isOutput = port.dataset.isOutput === '1';
        this.editor.startWireDrag(this.id, idx, isOutput, port);
      });
    });

    // Props 편집
    this.el.querySelectorAll('.fw-prop-input').forEach(input => {
      input.addEventListener('change', (e) => {
        const key = e.target.dataset.key;
        this.def.props[key] = e.target.value;
      });
      input.addEventListener('mousedown', (e) => e.stopPropagation());
    });

    // 선택
    this.el.addEventListener('mousedown', () => {
      this.editor._selectNode(this.id);
    });
  }
}

// ─── 전역 CSS ─────────────────────────────────────────────────────

function injectStyles() {
  if (document.getElementById('fw-styles')) return;
  const style = document.createElement('style');
  style.id = 'fw-styles';
  style.textContent = `
    .fw-node.selected { border-color: #58a6ff !important; box-shadow: 0 0 0 2px rgba(88,166,255,.2), 0 4px 16px rgba(0,0,0,.5) !important; }
    .fw-port:hover { transform: scale(1.4); }
    .fw-btn {
      padding: 5px 11px;
      background: rgba(255,255,255,.07);
      border: 1px solid #30363d;
      border-radius: 5px;
      color: #e6edf3;
      cursor: pointer;
      font-size: 12px;
      transition: background .12s;
    }
    .fw-btn:hover { background: rgba(255,255,255,.13); }
    .fw-btn-sm { padding: 2px 8px; font-size: 11px; }
    .fw-palette-item:active { opacity: 0.7; }
  `;
  document.head.appendChild(style);
}

module.exports = { NodeEditorUI, injectStyles };

