/**
 * FreeWire Phase 4 - Node Editor UI 단위 테스트
 * (브라우저 DOM 없는 로직 레이어 테스트)
 */

'use strict';

let passed = 0, failed = 0;

function test(name, fn) {
  try {
    fn();
    passed++;
    console.log(`  ✅ ${name}`);
  } catch (e) {
    failed++;
    console.error(`  ❌ ${name}\n     ${e.message}`);
  }
}

function assert(cond, msg) { if (!cond) throw new Error(msg ?? 'Assertion failed'); }
function eq(a, b) { if (a !== b) throw new Error(`Expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`); }

// ─── 포트 호환성 ──────────────────────────────────────────────────

const PORT_COMPAT = {
  component: ['component', 'any'],
  data:      ['data', 'any'],
  logic:     ['logic', 'any'],
  event:     ['event', 'any'],
  any:       ['component', 'data', 'logic', 'event', 'any'],
};

function isCompatible(outType, inType) {
  return (PORT_COMPAT[outType] ?? []).includes(inType);
}

console.log('\n📋 FreeWire Phase 4 - Node Editor 테스트\n');

// 1. 포트 호환성
test('component → component 연결 가능', () => assert(isCompatible('component', 'component')));
test('data → data 연결 가능', () => assert(isCompatible('data', 'data')));
test('logic → logic 연결 가능', () => assert(isCompatible('logic', 'logic')));
test('event → event 연결 가능', () => assert(isCompatible('event', 'event')));
test('any → 모든 타입 가능', () => {
  for (const t of ['component','data','logic','event','any']) {
    assert(isCompatible('any', t), `any → ${t} 실패`);
  }
});
test('component → data 연결 불가', () => assert(!isCompatible('component', 'data')));
test('data → logic 연결 불가', () => assert(!isCompatible('data', 'logic')));
test('logic → component 연결 불가', () => assert(!isCompatible('logic', 'component')));
test('data → any 연결 가능', () => assert(isCompatible('data', 'any')));
test('logic → any 연결 가능', () => assert(isCompatible('logic', 'any')));

// 2. 베지어 곡선 생성
function bez(x1,y1,x2,y2) {
  const dx = Math.abs(x2-x1)*0.6+40;
  return `M ${x1} ${y1} C ${x1+dx} ${y1}, ${x2-dx} ${y2}, ${x2} ${y2}`;
}

test('베지어: 기본 형식', () => {
  const d = bez(0,0,100,100);
  assert(d.startsWith('M 0 0 C'), '시작 M');
  assert(d.includes(', 100 100'), '끝점 포함');
});

test('베지어: 수평 선', () => {
  const d = bez(0,50,200,50);
  assert(d.includes('50'), 'y값 포함');
});

test('베지어: 역방향', () => {
  const d = bez(200,100,50,100);
  assert(d.startsWith('M 200 100'), '역방향 시작');
});

// 3. 그래프 직렬화 로직

class GraphModel {
  constructor() {
    this.nodes = new Map();
    this.wires = new Map();
    this.nodeCtr = 1;
    this.wireCtr = 1;
  }

  addNode(def, x=100, y=100) {
    const id = `n${this.nodeCtr++}`;
    this.nodes.set(id, { id, ...def, x, y });
    return id;
  }

  removeNode(id) {
    for (const [wid, w] of this.wires) {
      if (w.fn===id || w.tn===id) this.wires.delete(wid);
    }
    this.nodes.delete(id);
  }

  addWire(fn, fp, tn, tp, pt) {
    // 중복 방지
    for (const w of this.wires.values()) {
      if (w.fn===fn && w.fp===fp && w.tn===tn && w.tp===tp) return null;
    }
    const id = `w${this.wireCtr++}`;
    this.wires.set(id, { id, fn, fp, tn, tp, pt });
    return id;
  }

  toJSON() {
    const nodes = {};
    for (const [id, n] of this.nodes) nodes[id] = { ...n };
    const edges = [...this.wires.values()].map(w=>({...w}));
    return { id:'test-graph', nodes, edges };
  }

  fromJSON(json) {
    this.nodes.clear(); this.wires.clear();
    for (const [id, nd] of Object.entries(json.nodes??{})) this.nodes.set(id, nd);
    for (const e of json.edges??[]) this.wires.set(e.id, e);
  }
}

test('노드 추가', () => {
  const g = new GraphModel();
  const id = g.addNode({ type:'component', subtype:'button', label:'버튼',
    inputs:[{name:'onClick',portType:'logic'}], outputs:[{name:'element',portType:'component'}], props:{label:'클릭'} });
  eq(g.nodes.size, 1);
  assert(id.startsWith('n'), 'id 접두어');
});

test('노드 제거 시 연결 와이어도 삭제', () => {
  const g = new GraphModel();
  const n1 = g.addNode({ type:'data', subtype:'const', label:'상수', inputs:[], outputs:[{name:'value',portType:'data'}], props:{value:'42'} });
  const n2 = g.addNode({ type:'component', subtype:'text', label:'텍스트', inputs:[{name:'content',portType:'data'}], outputs:[{name:'element',portType:'component'}], props:{} });
  g.addWire(n1,0,n2,0,'data');
  eq(g.wires.size, 1);
  g.removeNode(n1);
  eq(g.wires.size, 0);
  eq(g.nodes.size, 1);
});

test('와이어 중복 방지', () => {
  const g = new GraphModel();
  const n1 = g.addNode({ type:'data', subtype:'const', label:'c', inputs:[], outputs:[{name:'v',portType:'data'}], props:{} });
  const n2 = g.addNode({ type:'component', subtype:'text', label:'t', inputs:[{name:'c',portType:'data'}], outputs:[], props:{} });
  g.addWire(n1,0,n2,0,'data');
  g.addWire(n1,0,n2,0,'data'); // 중복
  eq(g.wires.size, 1);
});

test('여러 노드 와이어 연결', () => {
  const g = new GraphModel();
  const ids = Array.from({length:4}, (_,i) => g.addNode({
    type: i===3?'component':'data', subtype:i===3?'container':'const', label:`n${i}`,
    inputs: i===3?[{name:'c',portType:'component'}]:[],
    outputs: [{name:'v',portType:i===3?'component':'data'}],
    props:{}
  }));
  g.addWire(ids[0],0,ids[1],0,'data');
  g.addWire(ids[1],0,ids[2],0,'data');
  eq(g.wires.size, 2);
});

test('그래프 JSON 직렬화', () => {
  const g = new GraphModel();
  const n1 = g.addNode({ type:'data', subtype:'state', label:'상태', inputs:[{name:'set',portType:'data'}], outputs:[{name:'value',portType:'data'}], props:{name:'count',initial:'0'} });
  const n2 = g.addNode({ type:'component', subtype:'text', label:'텍스트', inputs:[{name:'content',portType:'data'}], outputs:[{name:'element',portType:'component'}], props:{content:'0'} });
  g.addWire(n1,0,n2,0,'data');

  const json = g.toJSON();
  assert(json.id === 'test-graph', 'graph id');
  assert(Object.keys(json.nodes).length === 2, '노드 2개');
  assert(json.edges.length === 1, '엣지 1개');
});

test('그래프 JSON 역직렬화', () => {
  const g = new GraphModel();
  const n1 = g.addNode({ type:'data', subtype:'const', label:'c', inputs:[], outputs:[{name:'v',portType:'data'}], props:{value:'10'} });
  const n2 = g.addNode({ type:'component', subtype:'text', label:'t', inputs:[{name:'c',portType:'data'}], outputs:[], props:{} });
  g.addWire(n1,0,n2,0,'data');

  const json = g.toJSON();
  const g2 = new GraphModel();
  g2.fromJSON(json);
  eq(g2.nodes.size, 2);
  eq(g2.wires.size, 1);
});

test('fromJSON 후 노드 데이터 보존', () => {
  const g = new GraphModel();
  g.addNode({ type:'data', subtype:'state', label:'상태', inputs:[], outputs:[{name:'v',portType:'data'}], props:{name:'myState',initial:'99'} }, 150, 200);

  const json = g.toJSON();
  const g2 = new GraphModel();
  g2.fromJSON(json);
  const node = [...g2.nodes.values()][0];
  eq(node.props.name, 'myState');
  eq(node.props.initial, '99');
  eq(node.x, 150);
  eq(node.y, 200);
});

// 4. 로컬 컴파일러 로직

function localCompile(graph) {
  const nodes = Object.values(graph.nodes ?? {});
  const comps = nodes.filter(n => n.type === 'component');
  const states = nodes.filter(n => n.type === 'data' && n.subtype === 'state');
  const lines = ['component MyApp {'];
  if (states.length) {
    lines.push('  state {');
    for (const s of states) lines.push(`    ${s.props?.name??'val'}: ${s.props?.initial??'0'}`);
    lines.push('  }');
  }
  if (comps.length) {
    lines.push('  markup {');
    for (const c of comps) {
      const p = Object.entries(c.props??{}).map(([k,v])=>`${k}: "${v}"`).join(', ');
      lines.push(`    ${c.subtype}(${p})`);
    }
    lines.push('  }');
  }
  lines.push('}');
  return lines.join('\n');
}

test('로컬 컴파일: 버튼 노드', () => {
  const g = new GraphModel();
  g.addNode({ type:'component', subtype:'button', label:'버튼',
    inputs:[], outputs:[], props:{label:'클릭',variant:'primary'} });
  const code = localCompile(g.toJSON());
  assert(code.includes('component MyApp'), '컴포넌트 선언');
  assert(code.includes('button('), '버튼 포함');
  assert(code.includes('클릭'), '레이블 포함');
});

test('로컬 컴파일: 상태 + 텍스트', () => {
  const g = new GraphModel();
  g.addNode({ type:'data', subtype:'state', label:'상태', inputs:[], outputs:[], props:{name:'count',initial:'0'} });
  g.addNode({ type:'component', subtype:'text', label:'텍스트', inputs:[], outputs:[], props:{content:'0',tag:'p'} });
  const code = localCompile(g.toJSON());
  assert(code.includes('state {'), 'state 블록');
  assert(code.includes('count: 0'), '상태 변수');
  assert(code.includes('markup {'), 'markup 블록');
  assert(code.includes('text('), '텍스트 컴포넌트');
});

test('로컬 컴파일: 빈 그래프', () => {
  const g = new GraphModel();
  const code = localCompile(g.toJSON());
  assert(code.includes('component MyApp'), '기본 컴포넌트');
  assert(code.endsWith('}'), '마지막 중괄호');
});

test('로컬 컴파일: 복합 (카운터 앱)', () => {
  const g = new GraphModel();
  g.addNode({ type:'data', subtype:'state', label:'카운트', inputs:[], outputs:[], props:{name:'count',initial:'0'} });
  g.addNode({ type:'component', subtype:'text', label:'표시', inputs:[], outputs:[], props:{content:'카운트',tag:'h2'} });
  g.addNode({ type:'component', subtype:'button', label:'증가', inputs:[], outputs:[], props:{label:'+1',variant:'primary'} });
  const code = localCompile(g.toJSON());
  assert(code.includes('count: 0'), '상태');
  assert(code.includes('text('), '텍스트');
  assert(code.includes('button('), '버튼');
});

// 5. 팔레트 데이터 검증

const NODE_PALETTE_TEST = [
  { label: '컴포넌트', nodes: [
    { label:'버튼', type:'component', subtype:'button', inputs:[{name:'props',portType:'data'},{name:'onClick',portType:'logic'}], outputs:[{name:'element',portType:'component'}], props:{label:'클릭'} },
    { label:'텍스트', type:'component', subtype:'text', inputs:[{name:'content',portType:'data'}], outputs:[{name:'element',portType:'component'}], props:{content:'텍스트'} },
  ]},
  { label:'데이터', nodes:[
    { label:'상수', type:'data', subtype:'const', inputs:[], outputs:[{name:'value',portType:'data'}], props:{value:'42'} },
    { label:'상태', type:'data', subtype:'state', inputs:[{name:'set',portType:'data'}], outputs:[{name:'value',portType:'data'}], props:{name:'count'} },
  ]},
  { label:'로직', nodes:[
    { label:'핸들러', type:'logic', subtype:'handler', inputs:[{name:'action',portType:'logic'}], outputs:[{name:'handler',portType:'logic'}], props:{name:'handleClick'} },
  ]},
];

test('팔레트 모든 그룹에 노드 존재', () => {
  for (const g of NODE_PALETTE_TEST) assert(g.nodes.length > 0, `${g.label} 그룹 비어있음`);
});

test('팔레트 노드 필수 필드 존재', () => {
  for (const g of NODE_PALETTE_TEST) {
    for (const n of g.nodes) {
      assert(n.label, `${n.subtype}: label 없음`);
      assert(n.type, `${n.subtype}: type 없음`);
      assert(Array.isArray(n.inputs), `${n.subtype}: inputs 배열 아님`);
      assert(Array.isArray(n.outputs), `${n.subtype}: outputs 배열 아님`);
    }
  }
});

test('팔레트 포트 타입 유효', () => {
  const validTypes = new Set(['component','data','logic','event','any']);
  for (const g of NODE_PALETTE_TEST) {
    for (const n of g.nodes) {
      for (const p of [...n.inputs,...n.outputs]) {
        assert(validTypes.has(p.portType), `${n.subtype}.${p.name}: 유효하지 않은 포트 타입 '${p.portType}'`);
      }
    }
  }
});

// 6. 뷰포트 계산

function fitViewCalc(nodes, canvasW, canvasH) {
  if (!nodes.length) return { x:0, y:0, scale:1 };
  const nw = 190, nh = 120;
  let minX=Infinity, minY=Infinity, maxX=-Infinity, maxY=-Infinity;
  for (const n of nodes) {
    minX=Math.min(minX,n.x); minY=Math.min(minY,n.y);
    maxX=Math.max(maxX,n.x+nw); maxY=Math.max(maxY,n.y+nh);
  }
  const pw=canvasW-60, ph=canvasH-200;
  const scale = Math.max(0.2,Math.min(1.5,Math.min(pw/(maxX-minX||1),ph/(maxY-minY||1))));
  const x = (canvasW-(maxX-minX)*scale)/2 - minX*scale;
  const y = (ph-(maxY-minY)*scale)/2 - minY*scale + 20;
  return { x, y, scale };
}

test('fitView: 단일 노드', () => {
  const r = fitViewCalc([{x:0,y:0}], 800, 600);
  assert(r.scale > 0, '스케일 양수');
  assert(r.scale <= 1.5, '최대 스케일 이하');
});

test('fitView: 스케일 범위 유지', () => {
  const r1 = fitViewCalc([{x:0,y:0},{x:5000,y:5000}], 800, 600);
  assert(r1.scale >= 0.2, '최소 스케일');
  const r2 = fitViewCalc([{x:0,y:0},{x:10,y:10}], 800, 600);
  assert(r2.scale <= 1.5, '최대 스케일');
});

test('fitView: 빈 노드 목록', () => {
  const r = fitViewCalc([], 800, 600);
  eq(r.scale, 1); eq(r.x, 0); eq(r.y, 0);
});

// ─── 결과 ────────────────────────────────────────────────────────

console.log('\n' + '─'.repeat(40));
console.log(`총 ${passed+failed}개 테스트: ✅ ${passed}개 통과, ❌ ${failed}개 실패`);
console.log('─'.repeat(40) + '\n');
process.exit(failed > 0 ? 1 : 0);

