// 4. 로컬 컴파일러 로직

function localCompile(graph) {
  const nodes = Object.values(graph.nodes ?? {});
  const comps = nodes.filter(n => n.type === 'component');
  const states = nodes.filter(n => n.type === 'data' && n.subtype === 'state');
  const lines = ['component MyApp {'];
  if (states.length) {
    lines.push('  state {');
    for (const s of states) lines.push(`    ${s.props?.name??'val'}: ${s.props?.initial??'0'}`);
    lines.push('  }');
  }
  if (comps.length) {
    lines.push('  markup {');
    for (const c of comps) {
      const p = Object.entries(c.props??{}).map(([k,v])=>`${k}: "${v}"`).join(', ');
      lines.push(`    ${c.subtype}(${p})`);
    }
    lines.push('  }');
  }
  lines.push('}');
  return lines.join('\n');
}

test('로컬 컴파일: 버튼 노드', () => {
  const g = new GraphModel();
  g.addNode({ type:'component', subtype:'button', label:'버튼',
    inputs:[], outputs:[], props:{label:'클릭',variant:'primary'} });
  const code = localCompile(g.toJSON());
  assert(code.includes('component MyApp'), '컴포넌트 선언');
  assert(code.includes('button('), '버튼 포함');
  assert(code.includes('클릭'), '레이블 포함');
});

test('로컬 컴파일: 상태 + 텍스트', () => {
  const g = new GraphModel();
  g.addNode({ type:'data', subtype:'state', label:'상태', inputs:[], outputs:[], props:{name:'count',initial:'0'} });
  g.addNode({ type:'component', subtype:'text', label:'텍스트', inputs:[], outputs:[], props:{content:'0',tag:'p'} });
  const code = localCompile(g.toJSON());
  assert(code.includes('state {'), 'state 블록');
  assert(code.includes('count: 0'), '상태 변수');
  assert(code.includes('markup {'), 'markup 블록');
  assert(code.includes('text('), '텍스트 컴포넌트');
});

test('로컬 컴파일: 빈 그래프', () => {
  const g = new GraphModel();
  const code = localCompile(g.toJSON());
  assert(code.includes('component MyApp'), '기본 컴포넌트');
  assert(code.endsWith('}'), '마지막 중괄호');
});

test('로컬 컴파일: 복합 (카운터 앱)', () => {
  const g = new GraphModel();
  g.addNode({ type:'data', subtype:'state', label:'카운트', inputs:[], outputs:[], props:{name:'count',initial:'0'} });
  g.addNode({ type:'component', subtype:'text', label:'표시', inputs:[], outputs:[], props:{content:'카운트',tag:'h2'} });
  g.addNode({ type:'component', subtype:'button', label:'증가', inputs:[], outputs:[], props:{label:'+1',variant:'primary'} });
  const code = localCompile(g.toJSON());
  assert(code.includes('count: 0'), '상태');
  assert(code.includes('text('), '텍스트');
  assert(code.includes('button('), '버튼');
});

// 5. 팔레트 데이터 검증

const NODE_PALETTE_TEST = [
  { label: '컴포넌트', nodes: [
    { label:'버튼', type:'component', subtype:'button', inputs:[{name:'props',portType:'data'},{name:'onClick',portType:'logic'}], outputs:[{name:'element',portType:'component'}], props:{label:'클릭'} },
    { label:'텍스트', type:'component', subtype:'text', inputs:[{name:'content',portType:'data'}], outputs:[{name:'element',portType:'component'}], props:{content:'텍스트'} },
  ]},
  { label:'데이터', nodes:[
    { label:'상수', type:'data', subtype:'const', inputs:[], outputs:[{name:'value',portType:'data'}], props:{value:'42'} },
    { label:'상태', type:'data', subtype:'state', inputs:[{name:'set',portType:'data'}], outputs:[{name:'value',portType:'data'}], props:{name:'count'} },
  ]},
  { label:'로직', nodes:[
    { label:'핸들러', type:'logic', subtype:'handler', inputs:[{name:'action',portType:'logic'}], outputs:[{name:'handler',portType:'logic'}], props:{name:'handleClick'} },
  ]},
];

test('팔레트 모든 그룹에 노드 존재', () => {
  for (const g of NODE_PALETTE_TEST) assert(g.nodes.length > 0, `${g.label} 그룹 비어있음`);
});

test('팔레트 노드 필수 필드 존재', () => {
  for (const g of NODE_PALETTE_TEST) {
    for (const n of g.nodes) {
      assert(n.label, `${n.subtype}: label 없음`);
      assert(n.type, `${n.subtype}: type 없음`);
      assert(Array.isArray(n.inputs), `${n.subtype}: inputs 배열 아님`);
      assert(Array.isArray(n.outputs), `${n.subtype}: outputs 배열 아님`);
    }
  }
});

test('팔레트 포트 타입 유효', () => {
  const validTypes = new Set(['component','data','logic','event','any']);
  for (const g of NODE_PALETTE_TEST) {
    for (const n of g.nodes) {
      for (const p of [...n.inputs,...n.outputs]) {
        assert(validTypes.has(p.portType), `${n.subtype}.${p.name}: 유효하지 않은 포트 타입 '${p.portType}'`);
      }
    }
  }
});

// 6. 뷰포트 계산

function fitViewCalc(nodes, canvasW, canvasH) {
  if (!nodes.length) return { x:0, y:0, scale:1 };
  const nw = 190, nh = 120;
  let minX=Infinity, minY=Infinity, maxX=-Infinity, maxY=-Infinity;
  for (const n of nodes) {
    minX=Math.min(minX,n.x); minY=Math.min(minY,n.y);
    maxX=Math.max(maxX,n.x+nw); maxY=Math.max(maxY,n.y+nh);
  }
  const pw=canvasW-60, ph=canvasH-200;
  const scale = Math.max(0.2,Math.min(1.5,Math.min(pw/(maxX-minX||1),ph/(maxY-minY||1))));
  const x = (canvasW-(maxX-minX)*scale)/2 - minX*scale;
  const y = (ph-(maxY-minY)*scale)/2 - minY*scale + 20;
  return { x, y, scale };
}

test('fitView: 단일 노드', () => {
  const r = fitViewCalc([{x:0,y:0}], 800, 600);
  assert(r.scale > 0, '스케일 양수');
  assert(r.scale <= 1.5, '최대 스케일 이하');
});

test('fitView: 스케일 범위 유지', () => {
  const r1 = fitViewCalc([{x:0,y:0},{x:5000,y:5000}], 800, 600);
  assert(r1.scale >= 0.2, '최소 스케일');
  const r2 = fitViewCalc([{x:0,y:0},{x:10,y:10}], 800, 600);
  assert(r2.scale <= 1.5, '최대 스케일');
});

test('fitView: 빈 노드 목록', () => {
  const r = fitViewCalc([], 800, 600);
  eq(r.scale, 1); eq(r.x, 0); eq(r.y, 0);
});

// ─── 결과 ────────────────────────────────────────────────────────

console.log('\n' + '─'.repeat(40));
console.log(`총 ${passed+failed}개 테스트: ✅ ${passed}개 통과, ❌ ${failed}개 실패`);
console.log('─'.repeat(40) + '\n');
process.exit(failed > 0 ? 1 : 0);

