/**
 * FreeWire Phase 5 - AI 노드 자동 생성기
 *
 * 텍스트 한 줄 → 노드 그래프 JSON 자동 생성
 *
 * 동작 방식:
 *   1. IntentParser: 자연어 → 의도 파악 (키워드 + 패턴)
 *   2. TemplateEngine: 의도 → 노드 배치 계획
 *   3. LayoutEngine: 노드 위치 자동 계산 (겹침 방지)
 *   4. (선택) LLM 브릿지: 로컬 서버 or Claude API 연동
 */

'use strict';

// ─── 노드 팩토리 ─────────────────────────────────────────────────

let _idCtr = 1;
const uid = () => `ai-${_idCtr++}`;

const NODE = {
  button: (label = '버튼', variant = 'primary') => ({
    id: uid(), type: 'component', subtype: 'button', label: `버튼[${label}]`,
    inputs: [{ name: 'props', portType: 'data' }, { name: 'onClick', portType: 'logic' }],
    outputs: [{ name: 'element', portType: 'component' }],
    props: { label, variant },
  }),

  text: (content = '텍스트', tag = 'p') => ({
    id: uid(), type: 'component', subtype: 'text', label: `텍스트[${content.slice(0,8)}]`,
    inputs: [{ name: 'content', portType: 'data' }],
    outputs: [{ name: 'element', portType: 'component' }],
    props: { content, tag },
  }),

  input: (placeholder = '입력', type = 'text') => ({
    id: uid(), type: 'component', subtype: 'input', label: `입력[${placeholder}]`,
    inputs: [{ name: 'value', portType: 'data' }, { name: 'onChange', portType: 'logic' }],
    outputs: [{ name: 'element', portType: 'component' }, { name: 'value', portType: 'data' }],
    props: { placeholder, type },
  }),

  card: (title = '카드') => ({
    id: uid(), type: 'component', subtype: 'card', label: `카드[${title}]`,
    inputs: [{ name: 'title', portType: 'data' }, { name: 'children', portType: 'component' }],
    outputs: [{ name: 'element', portType: 'component' }],
    props: { title },
  }),

  container: (direction = 'column') => ({
    id: uid(), type: 'component', subtype: 'container', label: `컨테이너`,
    inputs: [{ name: 'children', portType: 'component' }],
    outputs: [{ name: 'element', portType: 'component' }],
    props: { direction, gap: '12px' },
  }),

  state: (name = 'value', initial = '0') => ({
    id: uid(), type: 'data', subtype: 'state', label: `상태[${name}]`,
    inputs: [{ name: 'set', portType: 'data' }],
    outputs: [{ name: 'value', portType: 'data' }],
    props: { name, initial },
  }),

  constant: (value = '', valueType = 'string') => ({
    id: uid(), type: 'data', subtype: 'const', label: `상수`,
    inputs: [],
    outputs: [{ name: 'value', portType: 'data' }],
    props: { value, valueType },
  }),

  array: (items = '[]') => ({
    id: uid(), type: 'data', subtype: 'array', label: `배열`,
    inputs: [],
    outputs: [{ name: 'items', portType: 'data' }],
    props: { items },
  }),

  handler: (name = 'handleClick') => ({
    id: uid(), type: 'logic', subtype: 'handler', label: `핸들러[${name}]`,
    inputs: [{ name: 'action', portType: 'logic' }],
    outputs: [{ name: 'handler', portType: 'logic' }],
    props: { name },
  }),

  setState: (target = 'value') => ({
    id: uid(), type: 'logic', subtype: 'setState', label: `setState[${target}]`,
    inputs: [{ name: 'trigger', portType: 'event' }, { name: 'value', portType: 'data' }],
    outputs: [{ name: 'done', portType: 'event' }],
    props: { target },
  }),

  condition: (operator = '==', value = 'true') => ({
    id: uid(), type: 'logic', subtype: 'condition', label: `조건`,
    inputs: [{ name: 'condition', portType: 'data' }],
    outputs: [{ name: 'true', portType: 'logic' }, { name: 'false', portType: 'logic' }],
    props: { operator, value },
  }),
};

// ─── 의도 파서 ────────────────────────────────────────────────────

class IntentParser {
  parse(text) {
    const t = text.toLowerCase().trim();

    // 1) 직접 패턴
    for (const [pattern, intent] of PATTERNS) {
      if (pattern.test(t)) return { ...intent, raw: text };
    }

    // 2) 키워드 추출로 복합 의도
    const keywords = this._extractKeywords(t);
    return this._buildFromKeywords(keywords, text);
  }

  _extractKeywords(t) {
    const kw = { components: [], data: [], logic: [], style: 'column', title: null };

    // 제목
    const titleMatch = t.match(/["']([^"']+)["']/) || t.match(/제목[은이]?\s*(.+?)(?:\s+|$)/);
    if (titleMatch) kw.title = titleMatch[1];

    // 컴포넌트
    if (/(버튼|button|클릭|submit|제출|확인|취소|저장|삭제|추가)/.test(t)) kw.components.push('button');
    if (/(텍스트|text|제목|title|label|표시|출력)/.test(t)) kw.components.push('text');
    if (/(입력|input|필드|field|이메일|email|비밀번호|password|이름|name|검색|search)/.test(t)) kw.components.push('input');
    if (/(카드|card)/.test(t)) kw.components.push('card');
    if (/(리스트|list|목록|항목)/.test(t)) kw.components.push('list');

    // 데이터
    if (/(상태|state|카운트|count)/.test(t)) kw.data.push('state');
    if (/(배열|array|list|목록|아이템)/.test(t)) kw.data.push('array');

    // 로직
    if (/(핸들러|클릭|이벤트|handler|event|onClick)/.test(t)) kw.logic.push('handler');
    if (/(조건|if|else|분기)/.test(t)) kw.logic.push('condition');

    // 레이아웃
    if (/(가로|row|수평|horizontal)/.test(t)) kw.style = 'row';

    return kw;
  }

  _buildFromKeywords(kw, raw) {
    // 컴포넌트가 없으면 일반 텍스트로
    if (kw.components.length === 0 && kw.data.length === 0) {
      return { type: 'generic', label: raw, raw };
    }
    return { type: 'custom', keywords: kw, raw };
  }
}

// 고정 패턴
const PATTERNS = [
  [/로그인|login|sign.?in/, { type: 'login' }],
  [/회원가입|register|sign.?up/, { type: 'register' }],
  [/카운터|counter|숫자\s*세기/, { type: 'counter' }],
  [/검색|search/, { type: 'search' }],
  [/(할일|todo|task)\s*(리스트|list|목록)?/, { type: 'todo' }],
  [/(프로필|profile)\s*(카드|card)?/, { type: 'profile-card' }],
  [/(댓글|comment)\s*(폼|form)?/, { type: 'comment-form' }],
  [/(결제|payment|checkout)\s*(폼|form)?/, { type: 'checkout' }],
  [/(설정|setting|config)\s*(폼|form|페이지)?/, { type: 'settings' }],
  [/(대시보드|dashboard)/, { type: 'dashboard' }],
  [/(모달|modal|팝업|popup)/, { type: 'modal' }],
  [/네비게이션|navbar|nav\s*bar/, { type: 'navbar' }],
  [/버튼/, { type: 'single-button' }],
  [/카드/, { type: 'single-card' }],
  [/(입력|input)\s*(폼|form)/, { type: 'input-form' }],
];

// ─── 템플릿 엔진 ──────────────────────────────────────────────────

class TemplateEngine {
  generate(intent) {
    const gen = TEMPLATES[intent.type];
    if (gen) return gen(intent);

    // 커스텀 키워드 기반
    if (intent.type === 'custom') return this._generateCustom(intent);

    // 폴백: 단순 텍스트 + 버튼
    return this._generateFallback(intent.raw);
  }

  _generateCustom(intent) {
    const { keywords } = intent;
    const nodes = [], edges = [];
    let hasContainer = keywords.components.length > 1;
    let container = null;

    if (hasContainer) {
      container = NODE.container(keywords.style);
      nodes.push(container);
    }

    // 데이터 먼저
    let stateNode = null;
    if (keywords.data.includes('state')) {
      stateNode = NODE.state('value', '0');
      nodes.push(stateNode);
    }

    let arrayNode = null;
    if (keywords.data.includes('array')) {
      arrayNode = NODE.array('["항목1","항목2","항목3"]');
      nodes.push(arrayNode);
    }

    // 컴포넌트
    for (const c of keywords.components) {
      let n;
      if (c === 'button') {
        n = NODE.button('확인');
        nodes.push(n);
        // 핸들러 연결
        if (keywords.logic.includes('handler')) {
          const h = NODE.handler('handleClick');
          nodes.push(h);
          edges.push({ from: h.id, fromPort: 0, to: n.id, toPort: 1 });
        }
      } else if (c === 'text') {
        n = NODE.text(keywords.title ?? '텍스트', 'p');
        nodes.push(n);
        if (stateNode) edges.push({ from: stateNode.id, fromPort: 0, to: n.id, toPort: 0 });
      } else if (c === 'input') {
        n = NODE.input('입력하세요');
        nodes.push(n);
      } else if (c === 'card') {
        n = NODE.card(keywords.title ?? '카드');
        nodes.push(n);
      }

      if (container && n) {
        edges.push({ from: n.id, fromPort: 0, to: container.id, toPort: 0 });
      }
    }

    return { nodes, edges, label: intent.raw };
  }

  _generateFallback(raw) {
    const t = NODE.text(raw.slice(0, 20), 'p');
    const b = NODE.button('확인');
    const c = NODE.container();
    return {
      nodes: [c, t, b],
      edges: [
        { from: t.id, fromPort: 0, to: c.id, toPort: 0 },
        { from: b.id, fromPort: 0, to: c.id, toPort: 0 },
      ],
      label: raw,
    };
  }
}

// ─── 템플릿 정의 ──────────────────────────────────────────────────

const TEMPLATES = {
  login: () => {
